// Formato: {s:"subtítulo"} abre trecho; {v,t,n} prosa; {v,l:[...]} verso;
// np:1 marca início de parágrafo.
// =====================================================================


window.TEXTOS_SEED["genesis"][1] = [
{s:"No princípio"},
{v:1,t:"No princípio criou Deus o céu e a terra.",n:"A primeira palavra hebraica, bereshit, admite também a leitura quando Deus começou a criar, e há quem a prefira. Sigo a construção absoluta, que é a da tradição e a da Nova Vulgata; é dela que São João toma o seu no princípio."},
{v:2,t:"A terra era informe e vazia, as trevas cobriam a face do abismo, e o espírito de Deus pairava sobre as águas.",n:"Informe e vazia traduz tohu wabohu, par de palavras que soam como um eco uma da outra e dizem o que ainda não tem forma nem conteúdo. O termo que se verte por espírito é também sopro e vento: os antigos ouviram as três coisas ao mesmo tempo."},
{v:3,t:"E disse Deus: Faça-se a luz. E a luz foi feita.",n:"Deus não luta com ninguém para criar, como nos mitos vizinhos: fala, e está feito. A luz aparece três dias antes do sol, o que já aos antigos advertia de que não se trata de uma crônica."},
{v:4,t:"Viu Deus que a luz era boa, e separou a luz das trevas."},
{v:5,t:"Chamou Deus à luz Dia, e às trevas chamou Noite. E houve tarde e manhã: dia primeiro.",n:"A tarde vem antes da manhã, e por isso o dia de Israel começa ao pôr do sol — donde o sábado que entra na sexta-feira à noite."},
{s:"O firmamento e a terra seca"},
{v:6,t:"Disse Deus: Faça-se um firmamento no meio das águas, que separe umas águas das outras."},
{v:7,t:"E fez Deus o firmamento, e separou as águas que estavam debaixo do firmamento das que estavam por cima dele. E assim se fez."},
{v:8,t:"Chamou Deus ao firmamento Céu. E houve tarde e manhã: dia segundo."},
{v:9,t:"Disse Deus: Juntem-se as águas que estão debaixo do céu num só lugar, e apareça o seco. E assim se fez."},
{v:10,t:"Chamou Deus ao seco Terra, e ao ajuntamento das águas chamou Mares. E viu Deus que era bom."},
{v:11,t:"Disse Deus: Produza a terra relva, ervas que deem semente e árvores frutíferas que deem fruto segundo a sua espécie, com a sua semente dentro, sobre a terra. E assim se fez."},
{v:12,t:"A terra produziu relva, ervas que dão semente segundo a sua espécie, e árvores que dão fruto com a semente dentro, segundo a sua espécie. E viu Deus que era bom."},
{v:13,t:"E houve tarde e manhã: dia terceiro."},
{s:"Os luzeiros"},
{v:14,t:"Disse Deus: Haja luzeiros no firmamento do céu, para separarem o dia da noite; sejam eles sinais para as estações, para os dias e para os anos;"},
{v:15,t:"e sirvam de luzeiros no firmamento do céu, para iluminarem a terra. E assim se fez."},
{v:16,t:"Fez Deus os dois grandes luzeiros: o maior para governar o dia, o menor para governar a noite; e fez também as estrelas.",n:"O texto evita de propósito os nomes sol e lua, que eram nomes de deuses nos povos vizinhos: aqui são lâmpadas, feitas para alumiar, e as estrelas vão no fim da frase, quase de passagem."},
{v:17,t:"E Deus os colocou no firmamento do céu, para iluminarem a terra,"},
{v:18,t:"para governarem o dia e a noite, e para separarem a luz das trevas. E viu Deus que era bom."},
{v:19,t:"E houve tarde e manhã: dia quarto."},
{s:"Os viventes das águas e do ar"},
{v:20,t:"Disse Deus: Fervilhem as águas de seres vivos, e voem aves sobre a terra, sob o firmamento do céu."},
{v:21,t:"Criou Deus os grandes monstros marinhos e todos os seres vivos que se movem, de que fervilham as águas, segundo as suas espécies, e toda ave alada segundo a sua espécie. E viu Deus que era bom;",n:"Os grandes monstros marinhos são, nos mitos de Canaã, os dragões primordiais com que o deus tinha de lutar antes de criar. Aqui figuram na lista das criaturas, entre dois versos tranquilos: não são rivais de Deus, são bichos que ele fez."},
{v:22,t:"e Deus os abençoou, dizendo: Crescei e multiplicai-vos, e enchei as águas do mar; e as aves se multipliquem sobre a terra."},
{v:23,t:"E houve tarde e manhã: dia quinto."},
{s:"Os animais e o homem"},
{v:24,t:"Disse Deus: Produza a terra seres vivos segundo a sua espécie: animais domésticos, répteis e feras da terra, segundo as suas espécies. E assim se fez."},
{v:25,t:"Fez Deus as feras da terra segundo as suas espécies, os animais domésticos segundo as suas espécies e todos os répteis do solo segundo a sua espécie. E viu Deus que era bom."},
{v:26,t:"E disse Deus: Façamos o homem à nossa imagem, conforme a nossa semelhança; e domine sobre os peixes do mar, sobre as aves do céu, sobre os animais domésticos, sobre toda a terra e sobre todos os répteis que se movem na terra.",n:"O plural intrigou sempre. Uns veem nele a corte celeste a quem Deus se dirige, outros um plural de deliberação; os Padres leram nele a Trindade. Note-se que o verbo seguinte volta ao singular: criou."},
{v:27,t:"E criou Deus o homem à sua imagem; à imagem de Deus o criou; macho e fêmea os criou.",n:"Três vezes o verbo criar, reservado no livro para o que só Deus faz. E a última linha diz que a imagem de Deus não está no varão sozinho: está nos dois."},
{v:28,t:"E Deus os abençoou, e Deus lhes disse: Crescei e multiplicai-vos, enchei a terra e sujeitai-a; dominai sobre os peixes do mar, sobre as aves do céu e sobre todos os animais que se movem sobre a terra."},
{v:29,t:"E disse Deus: Eis que vos dou toda erva que dá semente, sobre a face de toda a terra, e toda árvore em que há fruto com semente: hão de servir-vos de alimento;"},
{v:30,t:"e a todos os animais da terra, a todas as aves do céu e a tudo o que se move sobre a terra e tem em si sopro de vida, dou toda erva verde por alimento. E assim se fez.",n:"No princípio ninguém come carne, nem os homens nem as feras. A licença de comer animais só virá depois do dilúvio, e virá com ressalvas."},
{v:31,t:"E viu Deus tudo o que tinha feito, e eis que era muito bom. E houve tarde e manhã: dia sexto."}
];

window.TEXTOS_SEED["genesis"][2] = [
{s:"O sétimo dia"},
{v:1,t:"Assim foram acabados o céu e a terra, e todo o seu exército."},
{v:2,t:"No sétimo dia completou Deus a obra que fizera, e descansou no sétimo dia de toda a obra que fizera."},
{v:3,t:"E abençoou Deus o sétimo dia e o santificou, porque nele descansou de toda a obra que criara e fizera.",n:"O sábado não é aqui um preceito, é um fato: está posto na criação antes de haver povo que o guarde. O Êxodo havia de fundar nele o terceiro mandamento."},
{s:"O homem formado do pó"},
{v:4,t:"Esta é a origem do céu e da terra, quando foram criados. No dia em que o Senhor Deus fez a terra e o céu,",n:"Estas são as origens: fórmula que reaparece dez vezes e reparte o livro inteiro, cada vez abrindo a história do que veio depois. É o esqueleto do Gênesis, e por ela se vê que o livro se entende a si mesmo como uma genealogia."},
{v:5,t:"não havia ainda no campo nenhum arbusto, e nenhuma erva do campo havia ainda brotado, porque o Senhor Deus não tinha feito chover sobre a terra, e não havia homem que cultivasse o solo;"},
{v:6,t:"mas subia da terra um manancial que regava toda a superfície do solo."},
{v:7,t:"Então o Senhor Deus formou o homem do pó do solo, e soprou-lhe nas narinas um sopro de vida; e o homem tornou-se um ser vivente.",n:"Homem é adam, e solo é adamá: o nome do homem é o da terra donde saiu. O verbo formar é o do oleiro, que trabalha o barro com as mãos — a distância entre este relato e o do capítulo anterior está toda aí."},
{s:"O jardim em Éden"},
{v:8,t:"E o Senhor Deus plantou um jardim em Éden, ao oriente, e ali pôs o homem que formara."},
{v:9,t:"O Senhor Deus fez brotar do solo toda árvore agradável à vista e boa para comer; e a árvore da vida no meio do jardim, e a árvore do conhecimento do bem e do mal."},
{v:10,t:"Saía de Éden um rio para regar o jardim, e dali se dividia em quatro braços."},
{v:11,t:"O nome do primeiro é Píson: é o que circunda toda a terra de Havilá, onde há ouro;"},
{v:12,t:"e o ouro daquela terra é bom; ali há bdélio e pedra de ônix."},
{v:13,t:"O nome do segundo rio é Geon: é o que circunda toda a terra de Cuxe."},
{v:14,t:"O nome do terceiro rio é Tigre: é o que corre ao oriente da Assíria. E o quarto rio é o Eufrates.",n:"Dois dos rios existem e são conhecidos; os outros dois ninguém jamais localizou. O jardim fica assim meio no mapa e meio fora dele."},
{v:15,t:"O Senhor Deus tomou o homem e o pôs no jardim de Éden, para o cultivar e o guardar.",n:"O trabalho é anterior ao pecado: o homem é posto no jardim com um ofício. O que virá depois, no capítulo 3, não é o trabalho, é a fadiga."},
{v:16,t:"E o Senhor Deus ordenou ao homem: De toda árvore do jardim comerás livremente;"},
{v:17,t:"mas da árvore do conhecimento do bem e do mal não comerás, porque no dia em que dela comeres certamente morrerás."},
{s:"A mulher"},
{v:18,t:"Disse o Senhor Deus: Não é bom que o homem esteja só; vou fazer-lhe uma auxiliar que lhe corresponda.",n:"A expressão hebraica diz, à letra, uma ajuda como diante dele: alguém à sua altura e de frente para ele. A mesma palavra ajuda é usada no saltério para Deus, e não tem em si nada de subalterno. É a primeira vez que se diz, nesta página, que alguma coisa não é boa."},
{v:19,t:"O Senhor Deus formou do solo todos os animais do campo e todas as aves do céu, e os trouxe ao homem, para ver como ele os chamaria; e todo nome que o homem desse aos seres vivos, esse seria o seu nome."},
{v:20,t:"O homem deu nome a todos os animais domésticos, às aves do céu e a todas as feras do campo; mas para o homem não se achou auxiliar que lhe correspondesse."},
{v:21,t:"Então o Senhor Deus fez cair um sono profundo sobre o homem; e, enquanto ele dormia, tomou uma das suas costelas e fechou a carne no seu lugar."},
{v:22,t:"E da costela que tomara do homem o Senhor Deus formou uma mulher, e a trouxe ao homem."},
{v:23,l:["Então o homem disse:","Esta, sim, é osso dos meus ossos","e carne da minha carne!","Esta se chamará varoa,","porque do varão foi tomada."],n:"O primeiro poema da Escritura, e é de reconhecimento. O trocadilho hebraico é entre ishshá, mulher, e ish, homem; o português só o alcança com varoa e varão, palavras hoje fora de uso, que conservo por causa do jogo."},
{v:24,t:"Por isso o homem deixará seu pai e sua mãe e se unirá à sua mulher; e serão uma só carne.",n:"Verso que o Senhor Jesus cita ao ser interrogado sobre o repúdio, e de que tira a conclusão: o que Deus uniu não o separe o homem."},
{v:25,t:"Estavam ambos nus, o homem e sua mulher, e não se envergonhavam."}
];

window.TEXTOS_SEED["genesis"][3] = [
{s:"A serpente"},
{v:1,t:"A serpente era o mais astuto de todos os animais do campo que o Senhor Deus tinha feito. E disse à mulher: É verdade que Deus vos proibiu comer de todas as árvores do jardim?",n:"Astuto, arum, soa como nus, arummim, do último verso anterior: o texto passa da nudez sem vergonha à astúcia por um jogo de sons. A serpente é um animal, feito por Deus como os outros; o livro não a identifica com ninguém, e só a tradição posterior lhe daria nome."},
{v:2,t:"Respondeu-lhe a mulher: Do fruto das árvores do jardim podemos comer;"},
{v:3,t:"mas do fruto da árvore que está no meio do jardim, disse Deus: Não comereis dele nem o tocareis, para que não morrais.",n:"Nem o tocareis não estava na ordem dada. A primeira coisa que a conversa produz é um mandamento mais pesado do que o verdadeiro — e um mandamento exagerado é mais fácil de quebrar."},
{v:4,t:"Então a serpente disse à mulher: De modo nenhum morrereis!"},
{v:5,t:"Deus sabe que, no dia em que dele comerdes, os vossos olhos se abrirão, e sereis como Deus, conhecedores do bem e do mal."},
{v:6,t:"Viu a mulher que a árvore era boa para comer, agradável aos olhos e desejável para dar entendimento; e tomou do seu fruto e comeu; deu também a seu marido, que estava com ela, e ele comeu.",n:"Que estava com ela: ele assistiu a tudo e nada disse. A repartição de culpas que vem a seguir tem este verso por trás."},
{v:7,t:"Abriram-se os olhos de ambos; e, conhecendo que estavam nus, coseram folhas de figueira e fizeram para si cintas."},
{s:"Onde estás?"},
{v:8,t:"Ouviram o rumor do Senhor Deus, que passeava no jardim à brisa do dia, e o homem e sua mulher esconderam-se da face do Senhor Deus, entre as árvores do jardim."},
{v:9,t:"O Senhor Deus chamou o homem e lhe disse: Onde estás?",n:"A primeira pergunta que Deus faz na Escritura, e não é pedido de informação. A segunda, no capítulo seguinte, será onde está o teu irmão."},
{v:10,t:"Ele respondeu: Ouvi o teu rumor no jardim e tive medo, porque estava nu; e escondi-me."},
{v:11,t:"Deus lhe disse: Quem te fez saber que estavas nu? Comeste, então, da árvore de que te ordenei que não comesses?"},
{v:12,t:"Respondeu o homem: A mulher que me deste por companheira, ela me deu da árvore, e eu comi.",n:"Acusa a mulher e, na mesma frase, acusa quem a deu. A mulher acusará a serpente; a serpente não tem a quem acusar, e é a única que não é interrogada."},
{v:13,t:"E o Senhor Deus disse à mulher: Por que fizeste isso? Respondeu a mulher: A serpente me enganou, e eu comi."},
{s:"A sentença"},
{v:14,l:["Então o Senhor Deus disse à serpente:","Porque fizeste isso,","maldita és entre todos os animais","e entre todas as feras do campo!","Sobre o teu ventre andarás","e pó comerás todos os dias da tua vida."]},
{v:15,l:["Porei inimizade entre ti e a mulher,","entre a tua descendência e a descendência dela:","esta te esmagará a cabeça,","e tu lhe ferirás o calcanhar."],n:"A frase é a primeira promessa de vitória sobre o mal, e por isso se chama desde os Padres o protoevangelho. O hebraico usa o mesmo verbo nas duas metades, o que a tradução não consegue guardar sem escolher: a cabeça é esmagada, o calcanhar é ferido, e o desenlace é desigual."},
{v:16,l:["À mulher disse:","Multiplicarei os sofrimentos da tua gravidez:","com dor darás à luz os filhos.","O teu desejo será para o teu marido,","e ele te dominará."],n:"Não é ordem, é diagnóstico: o livro descreve o que passou a ser, não o que devia ser. O domínio do marido figura entre as consequências do pecado, ao lado do espinho e do suor."},
{v:17,l:["E ao homem disse:","Porque deste ouvidos à voz da tua mulher","e comeste da árvore de que eu te ordenara que não comesses,","maldito é o solo por tua causa!","Com fadiga dele comerás todos os dias da tua vida."]},
{v:18,l:["Espinhos e cardos te produzirá,","e comerás a erva do campo."]},
{v:19,l:["Com o suor do teu rosto comerás o teu pão,","até que voltes ao solo,","porque dele foste tomado:","pois és pó, e ao pó voltarás."],n:"Palavras com que a Igreja impõe as cinzas no princípio da Quaresma. Note-se que o homem não é amaldiçoado: o que se amaldiçoa é o solo, e ao homem toca o cansaço."},
{s:"Expulsos do jardim"},
{v:20,t:"E o homem deu à sua mulher o nome de Eva, porque ela foi a mãe de todos os viventes.",n:"Eva soa como a palavra hebraica de viver. Acabada de ouvir a sentença de morte, o homem dá à mulher o nome da vida."},
{v:21,t:"O Senhor Deus fez para o homem e sua mulher túnicas de pele, e os vestiu.",n:"O último gesto de Deus no jardim é vestir quem vai expulsar. As cintas de folhas do verso 7 eram obra deles; a roupa que dura é dada."},
{v:22,t:"E disse o Senhor Deus: Eis que o homem se tornou como um de nós, conhecedor do bem e do mal. Que agora não estenda a mão e tome também da árvore da vida, e coma, e viva para sempre!"},
{v:23,t:"E o Senhor Deus o lançou fora do jardim de Éden, para cultivar o solo de que fora tomado."},
{v:24,t:"Expulsou o homem e pôs, ao oriente do jardim de Éden, os querubins e a chama da espada fulgurante, para guardarem o caminho da árvore da vida."}
];

window.TEXTOS_SEED["genesis"][4] = [
{s:"Caim e Abel"},
{v:1,t:"O homem conheceu Eva, sua mulher; ela concebeu e deu à luz Caim, e disse: Adquiri um varão com o auxílio do Senhor.",n:"Caim soa como o verbo adquirir. A mãe do primeiro homem nascido de mulher dá-lhe um nome de posse, e diz que o recebeu com Deus."},
{v:2,t:"E deu à luz também Abel, seu irmão. Abel foi pastor de ovelhas, e Caim, lavrador do solo.",n:"Abel, em hebraico, é a mesma palavra com que o Eclesiastes há de começar: sopro, vapor, coisa que não dura. O nome do segundo filho já diz o que lhe vai acontecer."},
{v:3,t:"Ao cabo de algum tempo, Caim ofereceu ao Senhor uma oblação dos frutos do solo;"},
{v:4,t:"e Abel ofereceu também dos primogênitos do seu rebanho e das gorduras deles. O Senhor olhou com agrado para Abel e para a sua oferta,"},
{v:5,t:"mas para Caim e para a sua oferta não olhou. Caim irou-se muito, e o seu rosto descaiu.",n:"O texto não diz por que uma oferta foi aceita e a outra não, e essa recusa de explicar é deliberada: o que se narra a seguir não depende de Caim ter ou não razão de queixa."},
{v:6,t:"Disse-lhe o Senhor: Por que estás irado, e por que descaiu o teu rosto?"},
{v:7,t:"Se procederes bem, não levantarás o rosto? Mas se não procederes bem, o pecado jaz à porta, à tua espreita; o seu desejo é contra ti, mas tu deves dominá-lo.",n:"O pecado é descrito como um animal agachado à entrada da casa. E a última frase, dita a quem já está resolvido, repete as palavras que no capítulo 3 se disseram à mulher sobre o marido — só que agora o que há de dominar é o homem, e o que há de ser dominado é o mal."},
{v:8,t:"Caim disse a Abel, seu irmão: Vamos ao campo. E, quando estavam no campo, Caim levantou-se contra Abel, seu irmão, e o matou.",n:"O texto hebraico recebido não traz o que Caim disse: a frase fica pela metade, e os antigos preencheram-na de vários modos. Vamos ao campo é o que leem os manuscritos samaritanos e as versões grega e siríaca, que a Nova Vulgata segue."},
{s:"Onde está teu irmão?"},
{v:9,t:"E o Senhor disse a Caim: Onde está Abel, teu irmão? Ele respondeu: Não sei; acaso sou eu o guarda de meu irmão?",n:"A pergunta responde à do jardim: ali era onde estás, aqui é onde está o teu irmão. E a resposta de Caim é a primeira mentira dita a Deus, seguida da pergunta que a Escritura inteira responderá que sim."},
{v:10,t:"Disse Deus: Que fizeste? A voz do sangue de teu irmão clama a mim desde o solo."},
{v:11,t:"Agora, pois, maldito serás, longe do solo que abriu a boca para receber da tua mão o sangue de teu irmão."},
{v:12,t:"Quando o cultivares, não te dará mais o seu produto; errante e fugitivo serás sobre a terra."},
{v:13,t:"Caim disse ao Senhor: O meu castigo é grande demais para o suportar."},
{v:14,t:"Eis que hoje me lanças da face do solo, e da tua face me esconderei; serei errante e fugitivo sobre a terra, e todo aquele que me encontrar me matará."},
{v:15,t:"Respondeu-lhe o Senhor: Não será assim; quem matar Caim será vingado sete vezes. E o Senhor pôs um sinal em Caim, para que não o matasse quem o encontrasse.",n:"O sinal de Caim não é marca de infâmia, mas de proteção: o assassino condenado sai debaixo da guarda de quem o condenou. A cadeia de vinganças, que o verso 24 mostrará desenfreada, é cortada aqui no primeiro elo."},
{v:16,t:"Caim saiu da presença do Senhor e habitou na terra de Nod, ao oriente de Éden."},
{s:"Os descendentes de Caim"},
{v:17,t:"Caim conheceu a sua mulher, que concebeu e deu à luz Henoc. Depois edificou uma cidade, e deu-lhe o nome de seu filho, Henoc."},
{v:18,t:"A Henoc nasceu Irad; Irad gerou Maviael; Maviael gerou Matusael; e Matusael gerou Lamec."},
{v:19,t:"Lamec tomou para si duas mulheres: uma chamava-se Ada, e a outra, Sela."},
{v:20,t:"Ada deu à luz Jabel, que foi o pai dos que habitam em tendas e criam gado."},
{v:21,t:"O nome de seu irmão era Jubal, que foi o pai de todos os que tocam cítara e flauta."},
{v:22,t:"Sela deu à luz Tubalcaim, que forjava toda sorte de instrumentos de bronze e de ferro. E a irmã de Tubalcaim foi Noema.",n:"A cidade, a música e a metalurgia nascem todas na linhagem do fratricida. O livro não condena as artes: nota apenas que a civilização cresce onde o sangue já correu."},
{v:23,l:["Lamec disse às suas mulheres:","Ada e Sela, ouvi a minha voz;","mulheres de Lamec, escutai a minha palavra:","matei um homem por me ferir,","e um jovem por me pisar."],n:"Primeiro canto de bravata da Escritura, e é de vingança desmedida: mata-se por um arranhão. A violência, uma vez começada, não guarda proporção."},
{v:24,l:["Se Caim será vingado sete vezes,","Lamec o será setenta vezes sete."],n:"Ao setenta vezes sete de Lamec responde, muitos séculos depois, o setenta vezes sete que o Senhor Jesus dá a Pedro como medida do perdão. A conta da vingança é revogada com o mesmo número."},
{s:"Set"},
{v:25,t:"Adão conheceu ainda a sua mulher, e ela deu à luz um filho, a quem chamou Set, dizendo: Deus me concedeu outra descendência em lugar de Abel, a quem Caim matou."},
{v:26,t:"Também a Set nasceu um filho, a quem chamou Enos. Foi então que se começou a invocar o nome do Senhor.",n:"Um começo em surdina, depois do capítulo do assassínio: a oração aparece na terceira geração, sem cerimônia nem templo, apenas como quem chama por alguém pelo nome."}
];

window.TEXTOS_SEED["genesis"][5] = [
{s:"O livro das gerações de Adão"},
{v:1,t:"Este é o livro das gerações de Adão. No dia em que Deus criou o homem, à semelhança de Deus o fez.",n:"São Mateus abre o seu evangelho com a mesma fórmula, livro da geração, aplicada a Jesus Cristo. A lista que se segue tem dez nomes, como a do capítulo 11 e como as listas reais da Mesopotâmia, em que os primeiros reis também vivem milhares de anos."},
{v:2,t:"Macho e fêmea os criou; e os abençoou, e lhes deu o nome de Homem, no dia em que foram criados."},
{v:3,t:"Adão viveu cento e trinta anos e gerou um filho à sua semelhança, conforme a sua imagem, e chamou-lhe Set.",n:"O que se diz de Deus no verso 1 diz-se agora do homem: a imagem passa de pai a filho. É o modo de o livro dizer que o pecado não apagou o que a criação pôs."},
{v:4,t:"Depois de gerar Set, Adão viveu oitocentos anos, e gerou filhos e filhas."},
{v:5,t:"Todo o tempo que Adão viveu foi de novecentos e trinta anos; e morreu.",n:"E morreu: o estribilho volta oito vezes neste capítulo, fechando cada vida. A única exceção será Henoc, no verso 24."},
{v:6,t:"Set viveu cento e cinco anos e gerou Enos.",np:1},
{v:7,t:"Depois de gerar Enos, Set viveu oitocentos e sete anos, e gerou filhos e filhas."},
{v:8,t:"Todos os dias de Set foram novecentos e doze anos; e morreu."},
{v:9,t:"Enos viveu noventa anos e gerou Cainã.",np:1},
{v:10,t:"Depois de gerar Cainã, Enos viveu oitocentos e quinze anos, e gerou filhos e filhas."},
{v:11,t:"Todos os dias de Enos foram novecentos e cinco anos; e morreu."},
{v:12,t:"Cainã viveu setenta anos e gerou Malaleel.",np:1},
{v:13,t:"Depois de gerar Malaleel, Cainã viveu oitocentos e quarenta anos, e gerou filhos e filhas."},
{v:14,t:"Todos os dias de Cainã foram novecentos e dez anos; e morreu."},
{v:15,t:"Malaleel viveu sessenta e cinco anos e gerou Jared.",np:1},
{v:16,t:"Depois de gerar Jared, Malaleel viveu oitocentos e trinta anos, e gerou filhos e filhas."},
{v:17,t:"Todos os dias de Malaleel foram oitocentos e noventa e cinco anos; e morreu."},
{v:18,t:"Jared viveu cento e sessenta e dois anos e gerou Henoc.",np:1},
{v:19,t:"Depois de gerar Henoc, Jared viveu oitocentos anos, e gerou filhos e filhas."},
{v:20,t:"Todos os dias de Jared foram novecentos e sessenta e dois anos; e morreu."},
{v:21,t:"Henoc viveu sessenta e cinco anos e gerou Matusalém.",np:1},
{v:22,t:"E Henoc andou com Deus trezentos anos, depois de gerar Matusalém, e gerou filhos e filhas."},
{v:23,t:"Todos os dias de Henoc foram trezentos e sessenta e cinco anos."},
{v:24,t:"Henoc andou com Deus, e desapareceu, porque Deus o tomou.",n:"Único da lista que não morre, e a sua vida é a mais curta — trezentos e sessenta e cinco anos, o número dos dias do ano. A Carta aos Hebreus dirá que foi transladado para não ver a morte; em torno dele cresceu, entre os judeus, toda uma literatura."},
{v:25,t:"Matusalém viveu cento e oitenta e sete anos e gerou Lamec.",np:1},
{v:26,t:"Depois de gerar Lamec, Matusalém viveu setecentos e oitenta e dois anos, e gerou filhos e filhas."},
{v:27,t:"Todos os dias de Matusalém foram novecentos e sessenta e nove anos; e morreu.",n:"O homem mais velho da Escritura, e morre justamente no ano do dilúvio, se se somam as contas do capítulo seguinte."},
{v:28,t:"Lamec viveu cento e oitenta e dois anos e gerou um filho,",np:1},
{v:29,t:"a quem chamou Noé, dizendo: Este nos consolará do nosso trabalho e da fadiga das nossas mãos, por causa do solo que o Senhor amaldiçoou.",n:"Noé soa como a palavra descansar, e Lamec explica-lhe o nome pela palavra consolar. É a primeira vez que alguém, na Escritura, espera de um recém-nascido que conserte o que está errado no mundo."},
{v:30,t:"Depois de gerar Noé, Lamec viveu quinhentos e noventa e cinco anos, e gerou filhos e filhas."},
{v:31,t:"Todos os dias de Lamec foram setecentos e setenta e sete anos; e morreu."},
{v:32,t:"Noé, aos quinhentos anos, gerou Sem, Cam e Jafé."}
];

window.TEXTOS_SEED["genesis"][6] = [
{s:"Os filhos de Deus e as filhas dos homens"},
{v:1,t:"Quando os homens começaram a multiplicar-se sobre a face da terra e lhes nasceram filhas,"},
{v:2,t:"vendo os filhos de Deus que as filhas dos homens eram formosas, tomaram para si mulheres dentre todas as que escolheram.",n:"Quem sejam os filhos de Deus o texto não explica: seres celestes, para a leitura mais antiga; descendentes de Set, para boa parte dos Padres. O episódio fica em quatro versos e serve de última prova de que a desordem chegou aonde não devia."},
{v:3,t:"E disse o Senhor: O meu espírito não permanecerá para sempre no homem, porque ele é carne; e os seus dias serão de cento e vinte anos."},
{v:4,t:"Naqueles dias havia gigantes sobre a terra, e também depois, quando os filhos de Deus se uniram às filhas dos homens e elas lhes deram filhos: estes são os valentes de outrora, homens de renome."},
{s:"A maldade do homem"},
{v:5,t:"Viu o Senhor que a maldade do homem era grande sobre a terra, e que todo desígnio do seu coração era só mau, continuamente."},
{v:6,t:"E o Senhor arrependeu-se de ter feito o homem sobre a terra, e doeu-se no seu coração.",n:"A frase é das mais ousadas da Escritura. Não se diz que Deus mudou de ideia por ignorância, mas que sofreu; a mesma palavra hebraica serve para o arrependimento e para o pesar. Os antigos leram-na como linguagem de quem fala à nossa medida."},
{v:7,t:"E disse o Senhor: Farei desaparecer da face da terra o homem que criei, desde o homem até aos animais, aos répteis e às aves do céu, porque me arrependo de os ter feito."},
{v:8,t:"Noé, porém, achou graça aos olhos do Senhor."},
{s:"A arca"},
{v:9,t:"Estas são as gerações de Noé. Noé era homem justo e íntegro entre os seus contemporâneos; Noé andava com Deus."},
{v:10,t:"E gerou três filhos: Sem, Cam e Jafé."},
{v:11,t:"A terra estava corrompida diante de Deus, e cheia de violência."},
{v:12,t:"Viu Deus a terra, e eis que estava corrompida, porque toda carne havia corrompido o seu caminho sobre a terra."},
{v:13,t:"E Deus disse a Noé: Chegou diante de mim o fim de toda carne, porque a terra está cheia de violência por causa deles; e eis que vou destruí-los juntamente com a terra."},
{v:14,t:"Faze para ti uma arca de madeira resinosa; farás compartimentos na arca e a calafetarás com betume por dentro e por fora.",n:"A palavra traduzida por arca só reaparece na Escritura a propósito do cesto em que Moisés foi posto nas águas do Nilo. São duas embarcações sem leme e sem remos: o que as salva não é a navegação."},
{v:15,t:"Farás a arca assim: o seu comprimento será de trezentos côvados; a largura, de cinquenta côvados; e a altura, de trinta côvados."},
{v:16,t:"Farás na arca uma abertura, e a acabarás a um côvado do alto; porás a porta da arca ao lado, e farás nela um primeiro, um segundo e um terceiro andar."},
{v:17,t:"E eis que vou trazer sobre a terra as águas do dilúvio, para destruir debaixo do céu toda carne em que há sopro de vida: tudo o que há na terra perecerá."},
{v:18,t:"Mas contigo estabelecerei a minha aliança; e entrarás na arca, tu e teus filhos, tua mulher e as mulheres de teus filhos contigo.",n:"Primeira vez que a palavra aliança aparece na Escritura. Antes da água subir, já está dita a razão por que a história não acaba aqui."},
{v:19,t:"E de tudo o que vive, de toda carne, farás entrar na arca dois de cada espécie, para que sobrevivam contigo: serão macho e fêmea."},
{v:20,t:"Das aves segundo a sua espécie, dos animais domésticos segundo a sua espécie e de todos os répteis do solo segundo a sua espécie: dois de cada um entrarão contigo, para poderem viver."},
{v:21,t:"E tu toma contigo de todo alimento que se possa comer, e armazena-o; e servirá de mantimento para ti e para eles."},
{v:22,t:"E Noé fez tudo conforme Deus lhe ordenara; assim fez.",n:"Noé não diz uma palavra em toda a sua história. Abraão discutirá com Deus, Moisés resistirá, Jonas fugirá; Noé constrói."}
];

window.TEXTOS_SEED["genesis"][7] = [
{s:"A entrada na arca"},
{v:1,t:"E o Senhor disse a Noé: Entra na arca, tu e toda a tua casa, porque te vi justo diante de mim nesta geração."},
{v:2,t:"De todos os animais puros tomarás sete casais, macho e fêmea; mas dos animais que não são puros, um casal, macho e fêmea;",n:"Aqui são sete casais dos animais puros; no capítulo anterior era um casal de cada espécie. O relato do dilúvio entrelaça duas tradições, e a Escritura conservou as duas sem as aparar — a contagem maior é a que permite depois o sacrifício do capítulo 8."},
{v:3,t:"e também das aves do céu, sete casais, macho e fêmea, para conservar a descendência sobre a face de toda a terra."},
{v:4,t:"Porque daqui a sete dias farei chover sobre a terra durante quarenta dias e quarenta noites, e exterminarei da face da terra todos os seres que fiz."},
{v:5,t:"E Noé fez conforme tudo o que o Senhor lhe ordenara."},
{v:6,t:"Noé tinha seiscentos anos quando as águas do dilúvio vieram sobre a terra."},
{v:7,t:"E Noé entrou na arca, com seus filhos, sua mulher e as mulheres de seus filhos, por causa das águas do dilúvio."},
{v:8,t:"Dos animais puros e dos que não são puros, das aves e de tudo o que rasteja sobre o solo,"},
{v:9,t:"entraram de dois em dois na arca, ter com Noé, macho e fêmea, como Deus ordenara a Noé."},
{v:10,t:"Passados os sete dias, as águas do dilúvio vieram sobre a terra."},
{s:"O dilúvio"},
{v:11,t:"No ano seiscentos da vida de Noé, no segundo mês, no dia dezessete do mês, romperam-se todas as fontes do grande abismo e abriram-se as comportas do céu;",n:"O mundo desfaz-se pelo avesso do primeiro capítulo: as águas de cima e as de baixo, que o firmamento separara, tornam a juntar-se. O dilúvio não é só castigo, é a criação a ser desfeita."},
{v:12,t:"e caiu chuva sobre a terra durante quarenta dias e quarenta noites."},
{v:13,t:"Naquele mesmo dia entraram na arca Noé, e Sem, Cam e Jafé, filhos de Noé, e a mulher de Noé, e as três mulheres de seus filhos com eles;"},
{v:14,t:"eles e todos os animais selvagens segundo a sua espécie, todos os animais domésticos segundo a sua espécie, todos os répteis que rastejam sobre a terra segundo a sua espécie, e todas as aves segundo a sua espécie, tudo o que voa e tem asas."},
{v:15,t:"Entraram na arca, ter com Noé, de dois em dois, de toda carne em que há sopro de vida."},
{v:16,t:"Os que entraram eram macho e fêmea de toda carne, como Deus lhe ordenara. E o Senhor fechou a porta atrás dele.",n:"Quem fecha a porta é Deus, não Noé. O último gesto antes da água é de quem guarda por fora os que estão dentro."},
{v:17,t:"O dilúvio veio sobre a terra durante quarenta dias; as águas cresceram e levantaram a arca, e ela se elevou acima da terra."},
{v:18,t:"As águas engrossaram e cresceram muito sobre a terra, e a arca flutuava sobre as águas."},
{v:19,t:"As águas subiram cada vez mais sobre a terra, e ficaram cobertos todos os montes altos que havia debaixo do céu."},
{v:20,t:"Quinze côvados acima subiram as águas, e os montes ficaram cobertos."},
{v:21,t:"Pereceu toda carne que se movia sobre a terra: aves, animais domésticos, feras e todos os répteis que rastejam sobre a terra, e todos os homens."},
{v:22,t:"Tudo o que tinha sopro de vida nas narinas, tudo o que havia em terra seca, morreu."},
{v:23,t:"Assim foram exterminados todos os seres que havia sobre a face da terra, desde o homem até aos animais, aos répteis e às aves do céu; foram exterminados da terra. Só restou Noé, e os que com ele estavam na arca."},
{v:24,t:"E as águas dominaram sobre a terra durante cento e cinquenta dias."}
];

window.TEXTOS_SEED["genesis"][8] = [
{s:"As águas baixam"},
{v:1,t:"Então Deus lembrou-se de Noé, e de todos os animais e de todo o gado que estavam com ele na arca; e Deus fez passar um vento sobre a terra, e as águas baixaram.",n:"Lembrou-se não quer dizer que tivesse esquecido: na Escritura, Deus lembrar-se de alguém é agir a seu favor. E o vento que passa sobre as águas é o mesmo sopro do segundo verso do livro — a criação recomeça com o mesmo gesto."},
{v:2,t:"Fecharam-se as fontes do abismo e as comportas do céu, e a chuva do céu foi retida."},
{v:3,t:"As águas foram-se retirando da terra, indo e voltando; e começaram a diminuir ao cabo de cento e cinquenta dias."},
{v:4,t:"No sétimo mês, no dia dezessete do mês, a arca repousou sobre os montes de Ararat."},
{v:5,t:"As águas foram diminuindo até ao décimo mês; e no décimo mês, no primeiro dia do mês, apareceram os cumes dos montes."},
{s:"O corvo e a pomba"},
{v:6,t:"Passados quarenta dias, Noé abriu a janela que fizera na arca"},
{v:7,t:"e soltou um corvo, que saiu, indo e voltando, até que as águas secaram sobre a terra."},
{v:8,t:"Soltou também uma pomba, para ver se as águas já tinham diminuído sobre a face do solo."},
{v:9,t:"Mas a pomba, não achando onde pousar o pé, voltou para ele, à arca, porque as águas cobriam ainda toda a terra. E ele estendeu a mão, tomou-a e recolheu-a consigo na arca."},
{v:10,t:"Esperou ainda outros sete dias, e tornou a soltar a pomba fora da arca."},
{v:11,t:"Ela voltou para ele, à tarde, trazendo no bico um ramo verde de oliveira. Assim Noé entendeu que as águas tinham diminuído sobre a terra.",n:"Deste verso vem o ramo de oliveira como sinal de paz, que atravessou os séculos e chegou às bandeiras. O texto diz apenas que a terra tornou a dar folha."},
{v:12,t:"Esperou ainda outros sete dias, e soltou a pomba, que não tornou mais a ele."},
{v:13,t:"No ano seiscentos e um, no primeiro mês, no primeiro dia do mês, as águas tinham secado sobre a terra. Noé removeu a cobertura da arca, olhou, e eis que a superfície do solo estava enxuta."},
{v:14,t:"No segundo mês, aos vinte e sete dias do mês, a terra estava seca."},
{s:"A saída da arca"},
{v:15,t:"Então Deus falou a Noé, dizendo:"},
{v:16,t:"Sai da arca, tu e a tua mulher, teus filhos e as mulheres de teus filhos contigo."},
{v:17,t:"Faze sair contigo todos os animais que estão contigo, de toda carne: as aves, os animais domésticos e todos os répteis que rastejam sobre a terra; que povoem a terra, e sejam fecundos e se multipliquem sobre ela."},
{v:18,t:"E Noé saiu, com seus filhos, sua mulher e as mulheres de seus filhos."},
{v:19,t:"Também todos os animais, todos os répteis e todas as aves, tudo o que se move sobre a terra, saíram da arca segundo as suas espécies."},
{v:20,t:"Noé edificou um altar ao Senhor e, tomando de todos os animais puros e de todas as aves puras, ofereceu holocaustos sobre o altar."},
{v:21,t:"E o Senhor aspirou o suave odor, e disse no seu coração: Nunca mais amaldiçoarei o solo por causa do homem, porque os desígnios do coração humano são maus desde a sua mocidade; nunca mais ferirei todo ser vivente, como fiz.",n:"A razão por que Deus não tornará a destruir é a mesma por que destruiu, no capítulo 6: o coração do homem é mau. Mudou a conclusão, não o diagnóstico. Daqui por diante o mundo há de durar por paciência, e não por mérito."},
{v:22,l:["Enquanto durar a terra,","não hão de cessar","sementeira e colheita,","frio e calor,","verão e inverno,","dia e noite."]}
];

window.TEXTOS_SEED["genesis"][9] = [
{s:"A aliança com Noé"},
{v:1,t:"E Deus abençoou Noé e seus filhos, e lhes disse: Sede fecundos, multiplicai-vos e enchei a terra."},
{v:2,t:"O temor e o espanto de vós estarão sobre todos os animais da terra, sobre todas as aves do céu e sobre tudo o que se move no solo; todos os peixes do mar estão entregues nas vossas mãos.",n:"A bênção repete a do capítulo 1, mas falta-lhe o domínio sereno: agora é temor e espanto. Entre o primeiro mundo e o segundo passou a violência, e os bichos aprenderam a fugir do homem."},
{v:3,t:"Tudo o que se move e vive vos servirá de alimento; como vos dei a erva verde, vos dou tudo."},
{v:4,t:"Somente não comereis a carne com a sua vida, isto é, com o seu sangue.",n:"A primeira lei dada à humanidade inteira, e não só a Israel. O Levítico e o Deuteronômio hão de repeti-la, e o concílio de Jerusalém a manterá entre as poucas coisas pedidas aos gentios."},
{v:5,t:"E também pedirei conta do vosso sangue, que é a vossa vida: pedirei conta dele a todo animal; e ao homem, ao seu próprio irmão, pedirei conta da vida do homem."},
{v:6,l:["Quem derramar o sangue do homem,","pelo homem será derramado o seu sangue,","porque à imagem de Deus","foi feito o homem."],n:"A frase é construída em espelho no hebraico, como se a sentença voltasse sobre si; e a razão dada não é a ordem social, mas a imagem de Deus, que faz de todo homem, e não só do israelita, coisa intocável."},
{v:7,t:"Vós, pois, sede fecundos e multiplicai-vos; povoai a terra e dominai sobre ela."},
{s:"O arco nas nuvens"},
{v:8,t:"Deus disse ainda a Noé e a seus filhos com ele:"},
{v:9,t:"Eis que estabeleço a minha aliança convosco e com a vossa descendência depois de vós,"},
{v:10,t:"e com todo ser vivente que está convosco: as aves, os animais domésticos e todas as feras da terra que estão convosco, todos os que saíram da arca, todos os animais da terra."},
{v:11,t:"Estabeleço a minha aliança convosco: nunca mais será exterminada toda carne pelas águas do dilúvio, nem haverá mais dilúvio para devastar a terra.",n:"A primeira aliança da Escritura não se faz com um povo, mas com a terra inteira e com os bichos; e é unilateral, pois nada se pede em troca. A garantia do mundo não depende do que o mundo fizer."},
{v:12,t:"E Deus disse: Este é o sinal da aliança que faço entre mim e vós, e todo ser vivente que está convosco, para todas as gerações:"},
{v:13,t:"ponho o meu arco nas nuvens, e ele será o sinal da aliança entre mim e a terra.",n:"A palavra é a do arco de guerra, não a do arco-íris: Deus pendura a sua arma no céu, com a corda para baixo. O sinal é posto para que Deus se lembre, não para que o homem se lembre — o verso 16 diz isso mesmo."},
{v:14,t:"Quando eu cobrir a terra de nuvens, aparecerá o arco nas nuvens,"},
{v:15,t:"e eu me lembrarei da minha aliança convosco e com todo ser vivente de toda carne; e as águas não se tornarão mais em dilúvio que destrua toda carne."},
{v:16,t:"O arco estará nas nuvens; e eu o verei, e me lembrarei da aliança perpétua entre Deus e todo ser vivente, de toda carne que há sobre a terra."},
{v:17,t:"E Deus disse a Noé: Este é o sinal da aliança que estabeleci entre mim e toda carne que há sobre a terra."},
{s:"Noé e seus filhos"},
{v:18,t:"Os filhos de Noé que saíram da arca eram Sem, Cam e Jafé; e Cam é o pai de Canaã."},
{v:19,t:"Estes três são os filhos de Noé, e deles se povoou toda a terra."},
{v:20,t:"Noé, que era lavrador, começou a plantar uma vinha;",n:"O primeiro a plantar vinha é o mesmo que fora chamado consolação; e a consolação que dela tira acaba mal. O livro conta o episódio sem uma palavra de juízo sobre a bebida."},
{v:21,t:"e, bebendo do vinho, embriagou-se e ficou nu no meio da sua tenda."},
{v:22,t:"Cam, pai de Canaã, viu a nudez de seu pai e foi contá-lo, fora, aos seus dois irmãos."},
{v:23,t:"Mas Sem e Jafé tomaram um manto, puseram-no sobre os próprios ombros e, andando para trás, cobriram a nudez de seu pai; tinham os rostos voltados, e não viram a nudez de seu pai."},
{v:24,t:"Quando Noé despertou do vinho e soube o que lhe fizera o seu filho mais novo,"},
{v:25,l:["disse:","Maldito seja Canaã!","Servo dos servos será para seus irmãos."],n:"Quem peca é Cam, e quem é amaldiçoado é Canaã, seu filho. A maldição serve, no livro, para explicar por que Israel havia de tomar a terra dos cananeus. Foi abusivamente invocada, em séculos recentes, para justificar a escravidão de povos inteiros: o texto não diz nada disso, e a leitura é indefensável."},
{v:26,l:["E disse:","Bendito o Senhor, Deus de Sem!","E seja Canaã seu servo."]},
{v:27,l:["Dilate Deus a Jafé,","e habite nas tendas de Sem;","e seja Canaã seu servo."]},
{v:28,t:"Noé viveu, depois do dilúvio, trezentos e cinquenta anos."},
{v:29,t:"E todos os dias de Noé foram novecentos e cinquenta anos; e morreu."}
];

window.TEXTOS_SEED["genesis"][10] = [
{s:"Os filhos de Jafé"},
{v:1,t:"Estas são as gerações dos filhos de Noé: Sem, Cam e Jafé; e a eles nasceram filhos depois do dilúvio.",n:"A tábua das nações reparte a humanidade inteira em setenta povos, e fá-lo por genealogia, não por conquista: todos os que habitam a terra são primos. Nenhum documento antigo do Oriente traça um mapa assim."},
{v:2,t:"Filhos de Jafé: Gomer, Magog, Madai, Javã, Tubal, Mosoc e Tiras."},
{v:3,t:"Filhos de Gomer: Asquenez, Rifat e Togorma."},
{v:4,t:"Filhos de Javã: Elisa, Társis, Quitim e Rodanim."},
{v:5,t:"Destes se repartiram as ilhas das nações, nas suas terras, cada um segundo a sua língua, as suas famílias e as suas nações."},
{s:"Os filhos de Cam"},
{v:6,t:"Filhos de Cam: Cuxe, Mesraim, Fut e Canaã."},
{v:7,t:"Filhos de Cuxe: Sabá, Havilá, Sabata, Regma e Sabataca. Filhos de Regma: Sabá e Dedan."},
{v:8,t:"Cuxe gerou Nemrod, que começou a ser poderoso na terra;"},
{v:9,t:"e era valente caçador diante do Senhor. Por isso se diz: Como Nemrod, valente caçador diante do Senhor.",n:"Nemrod é o primeiro rei nomeado na Escritura, e vem da linhagem de Cam. O provérbio que o cita já corria quando o livro se escreveu; a tradição posterior fez dele o construtor da torre do capítulo seguinte."},
{v:10,t:"O princípio do seu reino foi Babel, Arac, Acad e Calane, na terra de Senaar."},
{v:11,t:"Daquela terra saiu para a Assíria, e edificou Nínive, Roobot-Ir, Cale,"},
{v:12,t:"e Resen, entre Nínive e Cale: esta é a cidade grande."},
{v:13,t:"Mesraim gerou os ludim, os anamim, os laabim, os neftuim,"},
{v:14,t:"os fetrusim, os casluim e os caftorim, donde saíram os filisteus."},
{v:15,t:"Canaã gerou Sidon, seu primogênito, e Het,"},
{v:16,t:"e o jebuseu, o amorreu, o gergeseu,"},
{v:17,t:"o heveu, o araceu, o sineu,"},
{v:18,t:"o aradeu, o samareu e o amateu. Depois disso se espalharam as famílias dos cananeus."},
{v:19,t:"E foram os limites dos cananeus desde Sidon, indo para Gerara, até Gaza; e indo para Sodoma, Gomorra, Adamá e Seboim, até Lesa."},
{v:20,t:"Estes são os filhos de Cam, segundo as suas famílias, as suas línguas, as suas terras e as suas nações."},
{s:"Os filhos de Sem"},
{v:21,t:"Também a Sem, pai de todos os filhos de Héber e irmão mais velho de Jafé, nasceram filhos.",n:"Héber é o nome de que vem, ao que tudo indica, a palavra hebreu. A genealogia estreita-se aqui: de toda a humanidade o livro vai ficando com uma linha só, até chegar a Abraão."},
{v:22,t:"Filhos de Sem: Elam, Assur, Arfaxad, Lud e Aram."},
{v:23,t:"Filhos de Aram: Us, Hul, Geter e Mes."},
{v:24,t:"Arfaxad gerou Sala, e Sala gerou Héber."},
{v:25,t:"A Héber nasceram dois filhos: um chamou-se Faleg, porque em seus dias se dividiu a terra; e seu irmão chamou-se Jectan."},
{v:26,t:"Jectan gerou Elmodad, Salef, Asarmot, Jaré,"},
{v:27,t:"Adoram, Uzal, Decla,"},
{v:28,t:"Ebal, Abimael, Sabá,"},
{v:29,t:"Ofir, Havilá e Jobab. Todos estes foram filhos de Jectan;"},
{v:30,t:"e a sua habitação ia de Messa, na direção de Sefar, até à montanha do oriente."},
{v:31,t:"Estes são os filhos de Sem, segundo as suas famílias, as suas línguas, as suas terras e as suas nações."},
{v:32,t:"Estas são as famílias dos filhos de Noé, segundo as suas gerações e as suas nações; e delas se repartiram os povos sobre a terra, depois do dilúvio."}
];

window.TEXTOS_SEED["genesis"][11] = [
{s:"A torre de Babel"},
{v:1,t:"Toda a terra tinha uma só língua e as mesmas palavras."},
{v:2,t:"Ao partirem do oriente, acharam uma planície na terra de Senaar, e ali habitaram."},
{v:3,t:"E disseram uns aos outros: Vinde, façamos tijolos e cozamo-los ao fogo. O tijolo serviu-lhes de pedra, e o betume, de argamassa.",n:"Os tijolos e o betume são os materiais da Mesopotâmia, que não tem pedra; o narrador explica-os a leitores que só constroem com pedra. O tom tem alguma ironia: o material da grande obra é barro cozido."},
{v:4,t:"E disseram: Vinde, edifiquemos para nós uma cidade e uma torre cujo cume chegue ao céu, e façamos para nós um nome, para que não sejamos dispersos sobre a face de toda a terra.",n:"As torres escalonadas da Babilônia diziam-se, de fato, ligações entre o céu e a terra. O que o livro censura não é a altura, é o motivo: fazer um nome para si. Fazer-lhe um nome é o que Deus há de prometer a Abraão no capítulo 12."},
{v:5,t:"E o Senhor desceu para ver a cidade e a torre que os filhos dos homens edificavam.",n:"A torre chega ao céu, e Deus tem de descer para a ver. O humor da frase é a resposta mais curta que o livro dá à ambição de quem a construiu."},
{v:6,t:"E o Senhor disse: Eis que são um só povo, e todos têm uma só língua; isto é o começo do que farão, e agora nada os impedirá de fazerem tudo o que planejarem."},
{v:7,t:"Vinde, desçamos e confundamos ali a sua língua, para que um não entenda a linguagem do outro.",n:"Ao vinde dos homens responde o vinde de Deus. Nem se diz que a confusão seja castigo: é o fim de uma unidade que se construía contra a ordem de encher a terra."},
{v:8,t:"E dali o Senhor os dispersou sobre a face de toda a terra, e cessaram de edificar a cidade."},
{v:9,t:"Por isso se chamou o seu nome Babel, porque ali confundiu o Senhor a língua de toda a terra, e dali o Senhor os dispersou sobre a face de toda a terra.",n:"Babel quer dizer, na própria Babilônia, porta do deus; o hebraico ouve nela o verbo balal, confundir, e devolve à capital do mundo um nome de trapalhada. No dia de Pentecostes, cada um ouvirá os apóstolos na sua própria língua: não se desfaz a dispersão, entende-se através dela."},
{s:"De Sem a Abraão"},
{v:10,t:"Estas são as gerações de Sem. Sem tinha cem anos quando gerou Arfaxad, dois anos depois do dilúvio;",n:"Segunda lista de dez nomes, como a do capítulo 5; mas as idades vão diminuindo de uma geração para outra, dos seiscentos anos de Sem aos duzentos e cinco de Taré. O mundo vai-se acomodando à medida humana."},
{v:11,t:"e viveu Sem, depois de gerar Arfaxad, quinhentos anos, e gerou filhos e filhas."},
{v:12,t:"Arfaxad viveu trinta e cinco anos e gerou Sala.",np:1},
{v:13,t:"E viveu Arfaxad, depois de gerar Sala, quatrocentos e três anos, e gerou filhos e filhas."},
{v:14,t:"Sala viveu trinta anos e gerou Héber.",np:1},
{v:15,t:"E viveu Sala, depois de gerar Héber, quatrocentos e três anos, e gerou filhos e filhas."},
{v:16,t:"Héber viveu trinta e quatro anos e gerou Faleg.",np:1},
{v:17,t:"E viveu Héber, depois de gerar Faleg, quatrocentos e trinta anos, e gerou filhos e filhas."},
{v:18,t:"Faleg viveu trinta anos e gerou Reu.",np:1},
{v:19,t:"E viveu Faleg, depois de gerar Reu, duzentos e nove anos, e gerou filhos e filhas."},
{v:20,t:"Reu viveu trinta e dois anos e gerou Serug.",np:1},
{v:21,t:"E viveu Reu, depois de gerar Serug, duzentos e sete anos, e gerou filhos e filhas."},
{v:22,t:"Serug viveu trinta anos e gerou Nacor.",np:1},
{v:23,t:"E viveu Serug, depois de gerar Nacor, duzentos anos, e gerou filhos e filhas."},
{v:24,t:"Nacor viveu vinte e nove anos e gerou Taré.",np:1},
{v:25,t:"E viveu Nacor, depois de gerar Taré, cento e dezenove anos, e gerou filhos e filhas."},
{v:26,t:"Taré viveu setenta anos e gerou Abrão, Nacor e Arã.",np:1},
{s:"A família de Taré"},
{v:27,t:"Estas são as gerações de Taré. Taré gerou Abrão, Nacor e Arã; e Arã gerou Lot."},
{v:28,t:"Arã morreu antes de Taré, seu pai, na terra do seu nascimento, em Ur dos caldeus."},
{v:29,t:"Abrão e Nacor tomaram mulheres: a mulher de Abrão chamava-se Sarai, e a mulher de Nacor, Melca, filha de Arã, que foi pai de Melca e de Jesca."},
{v:30,t:"Sarai era estéril, e não tinha filhos.",n:"Em quatro palavras o livro põe o obstáculo de que viverá toda a história seguinte. A promessa de uma descendência inumerável há de ser feita a este casal, e não a outro."},
{v:31,t:"Taré tomou Abrão, seu filho, e Lot, filho de Arã, seu neto, e Sarai, sua nora, mulher de Abrão, seu filho, e os fez sair de Ur dos caldeus, para irem à terra de Canaã. Chegaram a Harã, e ali ficaram.",n:"Quem sai de Ur para Canaã é o pai, e não Abrão; e para no meio do caminho. A vocação do capítulo seguinte há de recomeçar, de Harã, a viagem que ficou interrompida."},
{v:32,t:"Os dias de Taré foram duzentos e cinco anos; e Taré morreu em Harã."}
];

window.TEXTOS_SEED["genesis"][12] = [
{s:"A vocação de Abrão"},
{v:1,t:"E o Senhor disse a Abrão: Sai da tua terra, da tua parentela e da casa de teu pai, para a terra que eu te mostrarei.",n:"Nada se disse antes de Abrão, nem por que foi escolhido: a Escritura não lhe dá mérito nenhum. As três coisas de que há de sair estão postas em ordem crescente de custo, e a terra para onde vai nem é nomeada."},
{v:2,l:["Farei de ti uma grande nação,","eu te abençoarei e engrandecerei o teu nome,","e tu serás uma bênção."],n:"Os construtores de Babel queriam fazer para si um nome; aqui o nome é dado. E a bênção não termina em quem a recebe: Abrão é abençoado para ser bênção."},
{v:3,l:["Abençoarei os que te abençoarem","e amaldiçoarei os que te amaldiçoarem;","e em ti serão abençoadas","todas as famílias da terra."],n:"São Paulo lê nesta última linha o Evangelho anunciado de antemão a Abraão. Ela fecha os onze capítulos de dispersão que vieram antes: a humanidade inteira, espalhada em Babel, torna a aparecer aqui como destinatária."},
{v:4,t:"Abrão partiu, como o Senhor lhe dissera, e Lot foi com ele. Abrão tinha setenta e cinco anos quando saiu de Harã.",n:"Abrão não responde nada. A obediência é narrada com um verbo, e essa sobriedade é o elogio."},
{v:5,t:"Abrão levou Sarai, sua mulher, e Lot, filho de seu irmão, e todos os bens que tinham adquirido, e as pessoas que lhes tinham nascido em Harã; e saíram para ir à terra de Canaã, e chegaram à terra de Canaã."},
{v:6,t:"Abrão atravessou a terra até ao lugar de Siquém, até ao carvalho de Moré. Nesse tempo os cananeus estavam na terra."},
{v:7,t:"E o Senhor apareceu a Abrão e disse: À tua descendência darei esta terra. E Abrão edificou ali um altar ao Senhor, que lhe aparecera.",n:"A promessa é feita no meio de uma terra que já tem dono, e ao homem cuja mulher é estéril. As duas dificuldades, a terra e o filho, governam toda a história que se segue."},
{v:8,t:"Dali passou à montanha que está ao oriente de Betel, e armou a sua tenda, tendo Betel ao ocidente e Hai ao oriente; ali edificou um altar ao Senhor e invocou o nome do Senhor."},
{v:9,t:"E Abrão foi caminhando, de acampamento em acampamento, para o Negueb."},
{s:"Abrão no Egito"},
{v:10,t:"Houve fome na terra, e Abrão desceu ao Egito, para ali morar como estrangeiro, porque a fome era grave na terra.",n:"Mal chega à terra prometida, tem de sair dela por falta de comida. A descida ao Egito por causa da fome há de repetir-se com Jacó, e dará no cativeiro."},
{v:11,t:"Quando estava para entrar no Egito, disse a Sarai, sua mulher: Bem sei que és mulher formosa;"},
{v:12,t:"quando os egípcios te virem, dirão: É a mulher dele; e me matarão, e a ti te deixarão viver."},
{v:13,t:"Dize, pois, que és minha irmã, para que me façam bem por tua causa, e a minha vida seja poupada graças a ti."},
{v:14,t:"Quando Abrão entrou no Egito, viram os egípcios que a mulher era muito formosa."},
{v:15,t:"Os oficiais do faraó a viram e a gabaram diante dele; e a mulher foi levada para a casa do faraó."},
{v:16,t:"E ele tratou bem a Abrão por causa dela; e Abrão teve ovelhas, bois, jumentos, servos, servas, jumentas e camelos."},
{v:17,t:"Mas o Senhor feriu o faraó e a sua casa com grandes pragas, por causa de Sarai, mulher de Abrão.",n:"Quem é castigado é o inocente, e quem lucra é o que mentiu. O livro conta a coisa sem comentar, como fará sempre com as faltas dos patriarcas: não os defende nem os condena."},
{v:18,t:"Então o faraó chamou Abrão e disse: Que é isto que me fizeste? Por que não me declaraste que era tua mulher?"},
{v:19,t:"Por que disseste: É minha irmã? De modo que eu a tomei por mulher! Agora, pois, aqui tens a tua mulher: toma-a e vai-te."},
{v:20,t:"E o faraó deu ordens a respeito dele aos seus homens, e eles o despediram, com sua mulher e tudo o que tinha."}
];

window.TEXTOS_SEED["genesis"][13] = [
{s:"Abrão e Lot separam-se"},
{v:1,t:"Abrão subiu do Egito para o Negueb, ele, sua mulher e tudo o que tinha, e Lot com ele."},
{v:2,t:"Abrão era muito rico em gado, prata e ouro."},
{v:3,t:"E foi, de acampamento em acampamento, do Negueb até Betel, ao lugar onde antes armara a tenda, entre Betel e Hai,"},
{v:4,t:"ao lugar do altar que fizera no princípio; e ali invocou o nome do Senhor."},
{v:5,t:"Também Lot, que ia com Abrão, tinha rebanhos, gado e tendas;"},
{v:6,t:"e a terra não lhes bastava para habitarem juntos, porque os seus bens eram muitos, e não podiam viver no mesmo lugar."},
{v:7,t:"Houve contenda entre os pastores do gado de Abrão e os pastores do gado de Lot. Nesse tempo habitavam na terra os cananeus e os ferezeus."},
{v:8,t:"Disse, pois, Abrão a Lot: Não haja contenda, por favor, entre mim e ti, nem entre os meus pastores e os teus, porque somos irmãos."},
{v:9,t:"Não está diante de ti toda a terra? Separa-te de mim, peço-te: se fores para a esquerda, irei para a direita; se escolheres a direita, irei para a esquerda.",n:"O mais velho cede a escolha ao mais novo, e o que tem a promessa da terra oferece-a inteira ao outro. É a primeira coisa que se conta de Abrão depois do episódio do Egito, e corrige-o."},
{v:10,t:"Lot levantou os olhos e viu que toda a planície do Jordão era bem regada, como o jardim do Senhor e como a terra do Egito, na direção de Segor — isto antes de o Senhor destruir Sodoma e Gomorra."},
{v:11,t:"Lot escolheu para si toda a planície do Jordão e partiu para o oriente; e separaram-se um do outro."},
{v:12,t:"Abrão habitou na terra de Canaã, e Lot nas cidades da planície, e armou as suas tendas até Sodoma."},
{v:13,t:"Ora, os homens de Sodoma eram muito maus e pecadores diante do Senhor.",n:"Lot escolheu pelo que os olhos viam, e o narrador acrescenta, no verso seguinte à escolha, o que os olhos não viam."},
{s:"A promessa da terra"},
{v:14,t:"E o Senhor disse a Abrão, depois que Lot se separou dele: Levanta os olhos e olha, do lugar onde estás, para o norte e para o sul, para o oriente e para o ocidente;"},
{v:15,t:"toda a terra que vês, eu a darei a ti e à tua descendência, para sempre."},
{v:16,t:"E farei a tua descendência como o pó da terra: se alguém puder contar o pó da terra, também a tua descendência se poderá contar."},
{v:17,t:"Levanta-te, percorre a terra no seu comprimento e na sua largura, porque a ti a hei de dar."},
{v:18,t:"Abrão mudou a sua tenda, foi e habitou junto aos carvalhos de Mambré, que estão em Hebron; e ali edificou um altar ao Senhor."}
];

window.TEXTOS_SEED["genesis"][14] = [
{s:"A guerra dos quatro reis"},
{v:1,t:"Naquele tempo, Anrafel, rei de Senaar, Arioc, rei de Elasar, Codorlaomor, rei de Elam, e Tadal, rei dos povos,",n:"Capítulo único no Gênesis: Abrão aparece nele como chefe militar, em meio a uma guerra internacional com nomes de reis que nenhuma outra fonte confirma. O estilo é o de uma crônica antiga, embutida aqui inteira."},
{v:2,t:"fizeram guerra contra Bara, rei de Sodoma, contra Bersa, rei de Gomorra, contra Senaab, rei de Adamá, contra Semeber, rei de Seboim, e contra o rei de Bela, que é Segor."},
{v:3,t:"Todos estes se ajuntaram no vale de Sidim, que é o mar Salgado."},
{v:4,t:"Doze anos tinham servido a Codorlaomor, e no décimo terceiro ano rebelaram-se."},
{v:5,t:"No décimo quarto ano vieram Codorlaomor e os reis que estavam com ele, e derrotaram os refaim em Astarot-Carnaim, os zuzim em Ham, os emim em Savé-Cariataim,"},
{v:6,t:"e os horreus nas suas montanhas de Seir, até El-Farã, que está junto ao deserto."},
{v:7,t:"Depois voltaram e vieram à fonte de Mesfat, que é Cades; e devastaram toda a região dos amalecitas, e também os amorreus que habitavam em Asason-Tamar."},
{v:8,t:"Saíram então o rei de Sodoma, o rei de Gomorra, o rei de Adamá, o rei de Seboim e o rei de Bela, que é Segor, e ordenaram batalha contra eles no vale de Sidim:"},
{v:9,t:"contra Codorlaomor, rei de Elam, Tadal, rei dos povos, Anrafel, rei de Senaar, e Arioc, rei de Elasar: quatro reis contra cinco."},
{v:10,t:"O vale de Sidim estava cheio de poços de betume; e os reis de Sodoma e de Gomorra fugiram e caíram neles, e os que restaram fugiram para a montanha."},
{v:11,t:"Os vencedores tomaram todos os bens de Sodoma e de Gomorra, e todos os seus mantimentos, e foram-se."},
{v:12,t:"Levaram também Lot, filho do irmão de Abrão, e os seus bens; ele habitava em Sodoma."},
{s:"Abrão liberta Lot"},
{v:13,t:"Um dos que escaparam veio dar a notícia a Abrão, o hebreu, que habitava junto aos carvalhos de Mambré, o amorreu, irmão de Escol e de Aner; estes eram aliados de Abrão.",n:"Primeira vez que a palavra hebreu aparece na Escritura, e é dita por estrangeiros, como quem aponta um forasteiro de fora do rio."},
{v:14,t:"Quando Abrão ouviu que seu parente fora levado cativo, armou os seus homens exercitados, nascidos em sua casa, em número de trezentos e dezoito, e os perseguiu até Dã;"},
{v:15,t:"e, dividindo-se contra eles de noite, ele e os seus servos, derrotou-os e perseguiu-os até Hobá, que fica à esquerda de Damasco."},
{v:16,t:"E trouxe de volta todos os bens, e também Lot, seu parente, com os seus bens, e ainda as mulheres e o povo."},
{s:"Melquisedec"},
{v:17,t:"O rei de Sodoma saiu-lhe ao encontro, depois que ele voltou de derrotar Codorlaomor e os reis que estavam com ele, no vale de Savé, que é o vale do Rei."},
{v:18,t:"E Melquisedec, rei de Salém, trouxe pão e vinho; ele era sacerdote do Deus Altíssimo.",n:"Aparece em dois versos, sem pai nem genealogia, e desaparece. O Salmo 110 fará dele a figura do sacerdócio do Messias, e a Carta aos Hebreus dedica-lhe um capítulo inteiro; a liturgia da Igreja o nomeia no cânon da missa, pelo pão e pelo vinho. Salém é tida por Jerusalém."},
{v:19,l:["Ele o abençoou, dizendo:","Bendito seja Abrão pelo Deus Altíssimo,","criador do céu e da terra;"]},
{v:20,l:["e bendito seja o Deus Altíssimo,","que entregou os teus inimigos nas tuas mãos.","E Abrão deu-lhe o dízimo de tudo."]},
{s:"Abrão recusa o despojo"},
{v:21,t:"O rei de Sodoma disse a Abrão: Dá-me as pessoas, e os bens toma-os para ti."},
{v:22,t:"Respondeu-lhe Abrão: Levanto a minha mão ao Senhor, Deus Altíssimo, criador do céu e da terra,"},
{v:23,t:"jurando que nem um fio nem uma correia de sandália tomarei de tudo o que é teu, para que não digas: Eu enriqueci Abrão;",n:"Recebe a bênção do sacerdote e recusa o dinheiro do rei. Abrão quer dever a sua riqueza à promessa e não ao agradecimento de Sodoma."},
{v:24,t:"nada para mim, a não ser o que os jovens comeram, e a parte dos homens que vieram comigo: Aner, Escol e Mambré; estes tomarão a sua parte."}
];

window.TEXTOS_SEED["genesis"][15] = [
{s:"Abrão creu no Senhor"},
{v:1,t:"Depois destas coisas, a palavra do Senhor veio a Abrão numa visão, dizendo: Não temas, Abrão: eu sou o teu escudo, e a tua recompensa será muito grande.",n:"Primeira vez que a Escritura usa a fórmula a palavra do Senhor veio a, que depois será a dos profetas. E o primeiro não temas dirigido a um homem."},
{v:2,t:"Respondeu Abrão: Senhor Deus, que me darás? Eu vou-me sem filhos, e o herdeiro da minha casa é Eliezer de Damasco."},
{v:3,t:"E acrescentou Abrão: Eis que não me deste descendência, e um servo nascido em minha casa será o meu herdeiro.",n:"A primeira palavra de Abrão a Deus é uma queixa. O livro não faz dele um homem sem dúvidas: faz dele um homem que discute e continua."},
{v:4,t:"E eis que a palavra do Senhor lhe foi dirigida: Não será esse o teu herdeiro; o que sair das tuas entranhas, esse será o teu herdeiro."},
{v:5,t:"E, tirando-o fora, disse-lhe: Olha para o céu e conta as estrelas, se és capaz de contá-las. E acrescentou: Assim será a tua descendência."},
{v:6,t:"E Abrão creu no Senhor, e isso lhe foi imputado como justiça.",n:"Verso decisivo na história da teologia: São Paulo funda nele, na Carta aos Romanos e na Carta aos Gálatas, a doutrina da justificação pela fé, notando que Abraão foi declarado justo antes de ser circuncidado e séculos antes de haver Lei. São Tiago cita-o também, para dizer que a fé se mostra pelas obras."},
{s:"A aliança entre as vítimas"},
{v:7,t:"E disse-lhe: Eu sou o Senhor, que te tirei de Ur dos caldeus, para te dar esta terra em possessão."},
{v:8,t:"Ele perguntou: Senhor Deus, como saberei que hei de possuí-la?"},
{v:9,t:"Respondeu o Senhor: Toma para mim uma novilha de três anos, uma cabra de três anos, um carneiro de três anos, uma rola e um pombinho."},
{v:10,t:"Abrão tomou todos estes animais, partiu-os pelo meio e pôs cada metade defronte da outra; mas as aves não partiu.",n:"Era o rito de jurar: os contratantes passavam entre os pedaços das vítimas, chamando sobre si a sorte delas se faltassem à palavra. Jeremias descreve a mesma cerimônia."},
{v:11,t:"Desceram aves de rapina sobre os cadáveres, e Abrão as enxotava."},
{v:12,t:"Ao pôr do sol, caiu sobre Abrão um sono profundo, e eis que um grande e escuro terror o assaltou."},
{v:13,t:"E foi dito a Abrão: Sabe com certeza que a tua descendência será peregrina em terra que não é sua; ali serão reduzidos à servidão e afligidos por quatrocentos anos."},
{v:14,t:"Mas eu julgarei a nação a quem servirem, e depois sairão com grandes riquezas."},
{v:15,t:"Tu irás em paz para junto de teus pais, e serás sepultado numa boa velhice."},
{v:16,t:"E na quarta geração voltarão para cá, porque até agora não se encheu a medida da iniquidade dos amorreus.",n:"A terra não é tirada dos amorreus por capricho nem antes do tempo; e o texto admite que, no momento em que fala, eles ainda não a mereceram perder. É dos raros lugares em que a Escritura mede a paciência de Deus para com os povos de Canaã."},
{v:17,t:"Posto o sol, houve escuridão densa; e eis um forno fumegante e uma tocha de fogo que passou por entre aqueles pedaços.",n:"Só Deus passa entre as vítimas; Abrão dorme. O juramento é de uma parte só, e o compromisso que se assume é inteiro de quem o faz."},
{v:18,t:"Naquele dia o Senhor fez aliança com Abrão, dizendo: À tua descendência darei esta terra, desde o rio do Egito até ao grande rio, o rio Eufrates:"},
{v:19,t:"os quenitas, os quenezeus, os cadmoneus,"},
{v:20,t:"os heteus, os ferezeus, os refaim,"},
{v:21,t:"os amorreus, os cananeus, os gergeseus e os jebuseus."}
];

window.TEXTOS_SEED["genesis"][16] = [
{s:"Agar e Ismael"},
{v:1,t:"Sarai, mulher de Abrão, não lhe dava filhos; mas tinha uma escrava egípcia, chamada Agar,"},
{v:2,t:"e disse a seu marido: Eis que o Senhor me impediu de dar à luz; vai, pois, à minha escrava; talvez por meio dela eu tenha filhos. E Abrão atendeu à voz de Sarai.",n:"Os contratos de casamento da Mesopotâmia previam esta solução, e a esposa estéril podia mesmo ser obrigada a ela: o filho da escrava contava-se como da senhora. Sarai faz o que a lei do seu tempo lhe facultava, e o resultado é o que se segue."},
{v:3,t:"Assim Sarai, mulher de Abrão, tomou Agar, a egípcia, sua escrava, ao cabo de dez anos de habitarem na terra de Canaã, e a deu por mulher a Abrão, seu marido."},
{v:4,t:"Ele a tomou, e ela concebeu; e, vendo-se grávida, começou a desprezar a sua senhora."},
{v:5,t:"Disse então Sarai a Abrão: Recaia sobre ti a afronta que me é feita. Eu pus a minha escrava nos teus braços; e ela, vendo-se grávida, despreza-me. O Senhor julgue entre mim e ti."},
{v:6,t:"Respondeu-lhe Abrão: A tua escrava está nas tuas mãos; faze dela o que te parecer bem. Sarai a maltratou, e ela fugiu da sua presença.",n:"Abrão lava as mãos, e as duas mulheres ficam sozinhas com o problema. O livro não poupa ninguém nesta página."},
{s:"O Deus que me vê"},
{v:7,t:"O anjo do Senhor encontrou-a junto a uma fonte de água no deserto, a fonte que está no caminho de Sur,"},
{v:8,t:"e disse: Agar, escrava de Sarai, donde vens e para onde vais? Ela respondeu: Fujo da presença de Sarai, minha senhora.",n:"É a primeira aparição de um anjo na Escritura, e é a uma escrava estrangeira, fugida, grávida e sozinha no deserto. Deus chama-a pelo nome, que ninguém usara até aqui."},
{v:9,t:"Disse-lhe o anjo do Senhor: Volta para a tua senhora e humilha-te sob a sua mão."},
{v:10,t:"E disse-lhe o anjo do Senhor: Multiplicarei de tal modo a tua descendência, que não se poderá contar de tão numerosa.",n:"A mesma promessa feita a Abrão é feita a ela, quase nas mesmas palavras — a única mulher da Escritura a receber uma promessa assim."},
{v:11,t:"E disse-lhe o anjo do Senhor: Eis que concebeste e darás à luz um filho, e lhe porás o nome de Ismael, porque o Senhor ouviu a tua aflição."},
{v:12,l:["Ele será como um jumento selvagem:","a sua mão contra todos,","e a mão de todos contra ele;","e acampará em frente de todos os seus irmãos."],n:"O jumento selvagem é, na poesia bíblica, o animal que ninguém doma e que vive no descampado. O oráculo não é insulto: descreve um povo do deserto, livre e indomável."},
{v:13,t:"E ela deu ao Senhor, que lhe falava, o nome de: Tu és o Deus que me vê. Porque disse: Não vi eu aqui as costas daquele que me vê?",n:"Agar é a única pessoa em toda a Escritura que dá um nome a Deus. A segunda metade do verso é obscura no hebraico, e nenhuma tradução a resolve sem escolher."},
{v:14,t:"Por isso se chamou aquele poço Lacai-Roi, isto é, poço do Vivente que me vê; está entre Cades e Barad."},
{v:15,t:"Agar deu à luz um filho a Abrão; e Abrão pôs ao filho que Agar lhe dera o nome de Ismael."},
{v:16,t:"Abrão tinha oitenta e seis anos quando Agar lhe deu Ismael."}
];

window.TEXTOS_SEED["genesis"][17] = [
{s:"A aliança e a circuncisão"},
{v:1,t:"Quando Abrão tinha noventa e nove anos, apareceu-lhe o Senhor e disse: Eu sou o Deus Todo-Poderoso; anda na minha presença e sê íntegro."},
{v:2,t:"Estabelecerei a minha aliança entre mim e ti, e te multiplicarei sobremaneira."},
{v:3,t:"Abrão prostrou-se com o rosto em terra, e Deus lhe disse:"},
{v:4,t:"Eis a minha aliança contigo: serás pai de uma multidão de nações;"},
{v:5,t:"e já não te chamarás Abrão, mas Abraão será o teu nome, porque te constituí pai de uma multidão de nações.",n:"Abrão quer dizer pai excelso; Abraão é ouvido como pai de multidão. Trocar o nome é, no Oriente antigo, coisa de senhor que toma alguém ao seu serviço; aqui a mudança é de uma letra só, e cabe nela toda a promessa."},
{v:6,t:"Hei de fazer-te crescer muitíssimo e farei de ti nações, e reis sairão de ti."},
{v:7,t:"Estabelecerei a minha aliança entre mim e ti, e a tua descendência depois de ti, nas suas gerações, por aliança eterna, para ser o teu Deus e o da tua descendência depois de ti."},
{v:8,t:"E darei a ti e à tua descendência depois de ti a terra das tuas peregrinações, toda a terra de Canaã, em possessão perpétua; e serei o Deus deles."},
{v:9,t:"Disse ainda Deus a Abraão: Tu, porém, guardarás a minha aliança, tu e a tua descendência depois de ti, nas suas gerações."},
{v:10,t:"Esta é a minha aliança, que guardareis entre mim e vós e a tua descendência depois de ti: todo varão entre vós será circuncidado;"},
{v:11,t:"circuncidareis a carne do vosso prepúcio, e isso será o sinal da aliança entre mim e vós.",n:"A circuncisão era praticada por vários povos vizinhos, geralmente na puberdade e como rito de casamento. Aqui é transposta para o oitavo dia, quando o menino nada escolhe: o sinal é recebido antes de se poder merecê-lo."},
{v:12,t:"Aos oito dias será circuncidado entre vós todo varão, em todas as vossas gerações: tanto o nascido em casa como o comprado por dinheiro a algum estrangeiro que não seja da tua descendência."},
{v:13,t:"Será circuncidado o nascido em tua casa e o comprado por teu dinheiro; e a minha aliança estará na vossa carne como aliança eterna."},
{v:14,t:"O varão incircunciso, cuja carne do prepúcio não for circuncidada, será eliminado do seu povo: quebrou a minha aliança."},
{s:"Sara terá um filho"},
{v:15,t:"Disse mais Deus a Abraão: A Sarai, tua mulher, não chamarás Sarai, mas Sara será o seu nome."},
{v:16,t:"Eu a abençoarei, e dela também te darei um filho; hei de abençoá-la, e ela se tornará nações; reis de povos sairão dela."},
{v:17,t:"Abraão prostrou-se com o rosto em terra e riu-se, dizendo no seu coração: A um homem de cem anos há de nascer um filho? E Sara, aos noventa anos, há de dar à luz?",n:"O pai da fé ri-se da promessa, e o texto conta-o sem embaraço. É o primeiro dos três risos que dão o nome a Isaac: este, o de Sara no capítulo seguinte, e o do nascimento."},
{v:18,t:"E disse a Deus: Oxalá Ismael viva diante de ti!"},
{v:19,t:"Mas Deus respondeu: Sara, tua mulher, te dará um filho, e lhe porás o nome de Isaac; e estabelecerei com ele a minha aliança, como aliança eterna para a sua descendência depois dele.",n:"Isaac quer dizer ele ri. O filho da promessa carrega no nome a descrença de seus pais, transformada em alegria."},
{v:20,t:"Quanto a Ismael, também te ouvi: eis que o abençoarei, o farei crescer e o multiplicarei sobremaneira; gerará doze príncipes, e farei dele uma grande nação."},
{v:21,t:"Mas a minha aliança estabelecerei com Isaac, que Sara te dará por este tempo, no ano que vem."},
{v:22,t:"E, acabando de falar com ele, Deus subiu de junto de Abraão."},
{v:23,t:"Então Abraão tomou Ismael, seu filho, e todos os nascidos em sua casa e todos os comprados por seu dinheiro, todos os varões da sua casa, e circuncidou-lhes a carne do prepúcio naquele mesmo dia, como Deus lhe ordenara."},
{v:24,t:"Abraão tinha noventa e nove anos quando foi circuncidado na carne do seu prepúcio;"},
{v:25,t:"e Ismael, seu filho, tinha treze anos quando foi circuncidado."},
{v:26,t:"No mesmo dia foram circuncidados Abraão e Ismael, seu filho;"},
{v:27,t:"e com ele foram circuncidados todos os homens da sua casa, os nascidos nela e os comprados por dinheiro a estrangeiros."}
];

window.TEXTOS_SEED["genesis"][18] = [
{s:"Os três visitantes"},
{v:1,t:"O Senhor apareceu a Abraão junto aos carvalhos de Mambré, quando ele estava sentado à entrada da tenda, no maior calor do dia."},
{v:2,t:"Levantando os olhos, viu três homens de pé diante dele. Assim que os viu, correu da entrada da tenda ao seu encontro e prostrou-se em terra,",n:"O texto passa, sem aviso, do Senhor no singular para três homens, e depois torna ao singular. Os Padres viram aqui uma insinuação da Trindade, e a mais célebre das ícones russas, de Rublev, pinta a cena; a Carta aos Hebreus lê-a de outro modo, lembrando que alguns, hospedando, acolheram anjos sem o saber."},
{v:3,t:"e disse: Meu senhor, se achei graça aos teus olhos, não passes adiante do teu servo."},
{v:4,t:"Traga-se um pouco de água, lavai os pés e descansai debaixo da árvore."},
{v:5,t:"Trarei um bocado de pão, para vos confortardes; depois passareis adiante, pois foi por isso que chegastes até ao vosso servo. Eles disseram: Faze como disseste."},
{v:6,t:"Abraão foi depressa à tenda, a Sara, e disse: Depressa, amassa três medidas de flor de farinha e faze bolos."},
{v:7,t:"Ele mesmo correu ao gado, tomou um novilho tenro e bom, e deu-o ao servo, que se apressou a prepará-lo."},
{v:8,t:"Tomou também manteiga e leite, e o novilho que preparara, e pôs tudo diante deles; e ficou de pé junto a eles, debaixo da árvore, enquanto comiam.",n:"Um bocado de pão prometido, e o que chega é um banquete. A hospitalidade de Abraão ficou sendo, no judaísmo e no Oriente cristão, o modelo de como se recebe um desconhecido."},
{s:"O riso de Sara"},
{v:9,t:"Perguntaram-lhe: Onde está Sara, tua mulher? Ele respondeu: Está aí na tenda."},
{v:10,t:"E um deles disse: Voltarei a ti por este tempo, e Sara, tua mulher, terá um filho. Sara escutava à entrada da tenda, atrás dele."},
{v:11,t:"Abraão e Sara eram velhos, de idade avançada; e a Sara já tinha cessado o costume das mulheres."},
{v:12,t:"Sara riu-se consigo mesma, dizendo: Depois de velha, e velho o meu senhor, ainda teria eu esse prazer?"},
{v:13,t:"E o Senhor disse a Abraão: Por que se riu Sara, dizendo: Será que realmente hei de dar à luz, sendo velha?",n:"Deus repete a Abraão o que ela dissera, mas cortando o pedaço em que ela chamava velho ao marido. A discrição tem sido notada com sorriso desde os comentadores antigos."},
{v:14,t:"Acaso é impossível alguma coisa ao Senhor? No tempo determinado voltarei a ti, por este tempo, e Sara terá um filho.",n:"A pergunta ressoará no anúncio do anjo a Maria, quando disser que nada é impossível a Deus; e é a mesma que o Senhor Jesus faz sobre os que se salvam."},
{v:15,t:"Sara negou, dizendo: Não me ri — porque teve medo. Mas ele disse: Não é assim: tu te riste."},
{s:"Abraão intercede por Sodoma"},
{v:16,t:"Levantaram-se dali aqueles homens e olharam na direção de Sodoma; e Abraão ia com eles, acompanhando-os."},
{v:17,t:"E o Senhor disse: Ocultarei eu a Abraão o que vou fazer,"},
{v:18,t:"sendo ele destinado a tornar-se uma nação grande e poderosa, e devendo nele ser abençoadas todas as nações da terra?"},
{v:19,t:"Pois eu o escolhi, para que ordene a seus filhos e à sua casa depois dele que guardem o caminho do Senhor, praticando a justiça e o direito, a fim de que o Senhor cumpra em favor de Abraão o que lhe prometeu."},
{v:20,t:"Disse, pois, o Senhor: O clamor contra Sodoma e Gomorra é grande, e o seu pecado é muito grave."},
{v:21,t:"Descerei e verei se as suas obras correspondem ao clamor que subiu até mim; e, se não, hei de sabê-lo."},
{v:22,t:"Os homens partiram dali e foram para Sodoma; mas Abraão ficou ainda de pé diante do Senhor."},
{v:23,t:"E, aproximando-se, disse: Destruirás o justo com o ímpio?",n:"Abraão não pede que se poupem os justos: pede que os justos salvem a cidade. É o único regateio com Deus em toda a Escritura, e quem o inicia é o homem."},
{v:24,t:"Se houver cinquenta justos na cidade, hás de destruí-los? Não perdoarás àquele lugar por causa dos cinquenta justos que nele houver?"},
{v:25,t:"Longe de ti fazeres tal coisa, matares o justo com o ímpio, e ser o justo tratado como o ímpio; longe de ti! O juiz de toda a terra não há de fazer justiça?",n:"A frase é a primeira vez que um homem pede contas a Deus em nome da justiça, e fá-lo invocando o que o próprio Deus é. Jó e os salmos hão de retomar a pergunta."},
{v:26,t:"Respondeu o Senhor: Se eu achar em Sodoma cinquenta justos dentro da cidade, perdoarei a todo o lugar por causa deles."},
{v:27,t:"E Abraão tornou a dizer: Eis que me atrevi a falar ao meu Senhor, eu que sou pó e cinza."},
{v:28,t:"E se aos cinquenta justos faltarem cinco? Destruirás por cinco toda a cidade? E ele disse: Não a destruirei, se achar ali quarenta e cinco."},
{v:29,t:"Abraão tornou a falar-lhe: E se ali se acharem quarenta? Respondeu: Não o farei, por causa dos quarenta."},
{v:30,t:"E disse: Não se irrite o meu Senhor, se eu falar: e se ali se acharem trinta? Respondeu: Não o farei, se achar ali trinta."},
{v:31,t:"E disse: Eis que me atrevi a falar ao meu Senhor: e se ali se acharem vinte? Respondeu: Não a destruirei, por causa dos vinte."},
{v:32,t:"E disse: Não se irrite o meu Senhor, e falarei só mais esta vez: e se ali se acharem dez? Respondeu: Não a destruirei, por causa dos dez.",n:"Abraão para em dez, e não em um. Coube à Escritura posterior, e sobretudo ao Servo de Isaías, chegar ao ponto em que um só justo basta para muitos."},
{v:33,t:"E o Senhor foi-se, quando acabou de falar a Abraão; e Abraão voltou para o seu lugar."}
];

window.TEXTOS_SEED["genesis"][19] = [
{s:"Os anjos em Sodoma"},
{v:1,t:"Os dois anjos chegaram a Sodoma ao cair da tarde, quando Lot estava sentado à porta da cidade. Ao vê-los, levantou-se, foi ao seu encontro e prostrou-se com o rosto em terra,"},
{v:2,t:"e disse: Peço-vos, meus senhores, vinde à casa do vosso servo e passai nela a noite; lavai os pés, e de manhã seguireis o vosso caminho. Eles responderam: Não; passaremos a noite na praça."},
{v:3,t:"Mas ele insistiu tanto que foram com ele e entraram em sua casa. Preparou-lhes um banquete, cozeu pães sem fermento, e eles comeram."},
{v:4,t:"Antes que se deitassem, os homens da cidade, os homens de Sodoma, cercaram a casa, desde o moço até ao velho, o povo todo, sem faltar ninguém;"},
{v:5,t:"e chamaram Lot, dizendo: Onde estão os homens que entraram esta noite em tua casa? Traze-os cá fora, para que os conheçamos.",n:"O crime que a cidade quer cometer é o estupro coletivo de hóspedes, e é assim que a Escritura posterior o entende: Ezequiel nomeia a culpa de Sodoma como soberba, fartura e desprezo do pobre e do necessitado. O livro dos Juízes conta um episódio quase igual, em Gabaá."},
{v:6,t:"Lot saiu a eles, à porta, fechando-a atrás de si,"},
{v:7,t:"e disse: Peço-vos, irmãos meus, não façais este mal."},
{v:8,t:"Tenho duas filhas que ainda não conheceram homem; eu vo-las trarei, e fazei delas o que vos parecer bem; mas a estes homens não façais nada, porque entraram sob a sombra do meu teto.",n:"A oferta é monstruosa, e o texto não a desculpa. Lot, que se apresenta como o justo de Sodoma, já está contaminado pelo lugar: para salvar a lei sagrada da hospitalidade entrega as filhas."},
{v:9,t:"Eles responderam: Sai daí! E acrescentaram: Este veio de fora, como estrangeiro, e quer fazer-se juiz? Agora te faremos pior do que a eles. E, fazendo grande violência a Lot, chegaram a arrombar a porta."},
{v:10,t:"Mas os homens estenderam a mão, puxaram Lot para dentro e fecharam a porta;"},
{v:11,t:"e feriram de cegueira os que estavam fora, do menor ao maior, de modo que não conseguiam achar a porta."},
{s:"A fuga de Lot"},
{v:12,t:"Os homens disseram a Lot: Tens aqui mais alguém dos teus? Genro, filhos, filhas, e todos os que são teus na cidade, tira-os deste lugar,"},
{v:13,t:"porque vamos destruir este lugar; o clamor contra eles subiu até diante do Senhor, e o Senhor nos enviou a destruí-lo."},
{v:14,t:"Lot saiu e falou a seus genros, que iam casar-se com as suas filhas, e disse: Levantai-vos, saí deste lugar, porque o Senhor vai destruir a cidade. Mas ele pareceu-lhes que estava brincando."},
{v:15,t:"Ao romper da aurora, os anjos apertavam com Lot, dizendo: Levanta-te, toma tua mulher e as duas filhas que aqui tens, para que não pereças no castigo da cidade."},
{v:16,t:"Como ele se demorasse, aqueles homens pegaram-no pela mão, e à sua mulher e às suas duas filhas, porque o Senhor teve compaixão dele;",n:"Lot não foge: é arrastado pela mão, como criança. O livro guarda o que salva e o que não louva, e o resumo é a única explicação que dá — porque o Senhor teve compaixão dele."},
{v:17,t:"e, tirando-os para fora, puseram-nos fora da cidade. E disseram: Salva a tua vida; não olhes para trás, nem pares em toda a planície; salva-te na montanha, para que não pereças."},
{v:18,t:"Mas Lot disse-lhes: Não, meu Senhor, peço-te."},
{v:19,t:"Eis que o teu servo achou graça aos teus olhos, e engrandeceste a tua misericórdia para comigo, salvando-me a vida; mas eu não poderei salvar-me na montanha, para que o mal não me alcance e eu morra."},
{v:20,t:"Eis ali aquela cidade, perto, para onde posso fugir; é pequena — não é pequena? — e nela salvarei a vida."},
{v:21,t:"Respondeu-lhe: Também nisto te atendo, e não destruirei a cidade de que falaste."},
{v:22,t:"Apressa-te, salva-te ali, porque nada poderei fazer enquanto não tiveres chegado lá. Por isso se chamou aquela cidade Segor.",n:"Segor soa como a palavra pequena, que Lot repete duas vezes. Até na fuga ele regateia, e obtém que se poupe uma cidade a mais — ele, a quem foi preciso arrastar pela mão."},
{s:"A destruição"},
{v:23,t:"O sol nascia sobre a terra quando Lot entrou em Segor."},
{v:24,t:"Então o Senhor fez chover sobre Sodoma e Gomorra enxofre e fogo, da parte do Senhor, desde o céu;"},
{v:25,t:"e destruiu aquelas cidades e toda a planície, todos os habitantes das cidades e as plantas do solo."},
{v:26,t:"E a mulher de Lot olhou para trás e ficou convertida numa estátua de sal.",n:"As formações salinas junto ao mar Morto ainda hoje se apontam ao viajante. O Senhor Jesus resume o episódio numa frase, das mais curtas do Evangelho: lembrai-vos da mulher de Lot."},
{v:27,t:"Abraão levantou-se de manhã cedo e foi ao lugar onde estivera diante do Senhor;"},
{v:28,t:"olhou para Sodoma e Gomorra e para toda a região da planície, e viu subir da terra uma fumaça como a fumaça de uma fornalha."},
{v:29,t:"Assim, quando Deus destruiu as cidades daquela planície, lembrou-se de Abraão e tirou Lot do meio da destruição das cidades em que habitara.",n:"O verso dá a chave do capítulo anterior: o regateio não salvou Sodoma, mas salvou Lot. Deus lembra-se de Abraão, e é pela memória do intercessor que o sobrinho é tirado."},
{s:"As filhas de Lot"},
{v:30,t:"Lot subiu de Segor e ficou na montanha, e com ele as suas duas filhas, porque teve medo de ficar em Segor; e habitou numa caverna, ele e as suas duas filhas."},
{v:31,t:"A mais velha disse à mais nova: Nosso pai é velho, e não há homem na terra que venha a nós, segundo o costume de toda a terra."},
{v:32,t:"Vem, embriaguemos nosso pai com vinho e deitemo-nos com ele, para conservarmos a descendência de nosso pai."},
{v:33,t:"Naquela noite deram vinho a beber a seu pai; e a mais velha entrou e deitou-se com ele, e ele não percebeu nem quando ela se deitou nem quando se levantou."},
{v:34,t:"No dia seguinte, a mais velha disse à mais nova: Ontem deitei-me com meu pai; demos-lhe vinho a beber também esta noite, e entra tu e deita-te com ele, para conservarmos a descendência de nosso pai."},
{v:35,t:"E naquela noite também deram vinho a beber a seu pai; e a mais nova entrou e deitou-se com ele, e ele não percebeu nem quando ela se deitou nem quando se levantou."},
{v:36,t:"Assim conceberam do próprio pai as duas filhas de Lot."},
{v:37,t:"A mais velha deu à luz um filho, e chamou-lhe Moab; este é o pai dos moabitas, até ao dia de hoje."},
{v:38,t:"A mais nova também deu à luz um filho, e chamou-lhe Benami; este é o pai dos amonitas, até ao dia de hoje.",n:"O episódio é uma explicação mordaz da origem dos dois vizinhos de Israel, contada por quem os não estimava. Note-se, porém, que da linha de Moab virá Rute, e dela Davi — a Escritura não deixa fechada nenhuma origem."}
];

window.TEXTOS_SEED["genesis"][20] = [
{s:"Abraão e Abimelec"},
{v:1,t:"Abraão partiu dali para a terra do Negueb, e habitou entre Cades e Sur; e morou como estrangeiro em Gerara."},
{v:2,t:"E dizia de Sara, sua mulher: É minha irmã. Então Abimelec, rei de Gerara, mandou buscá-la e tomou-a.",n:"Terceira vez que o Gênesis conta a história da mulher dada por irmã: duas com Abraão e uma com Isaac, no capítulo 26. A crítica vê nelas três versões de um mesmo relato, guardadas lado a lado."},
{v:3,t:"Mas Deus veio a Abimelec, de noite, em sonho, e disse-lhe: Vais morrer por causa da mulher que tomaste, porque ela tem marido."},
{v:4,t:"Abimelec, que ainda não se aproximara dela, disse: Senhor, matarás também uma nação justa?"},
{v:5,t:"Não me disse ele: É minha irmã? E ela também disse: É meu irmão. Na integridade do meu coração e na inocência das minhas mãos fiz isto."},
{v:6,t:"E Deus lhe disse em sonho: Também eu sei que o fizeste na integridade do teu coração, e por isso te impedi de pecar contra mim; não te deixei tocá-la."},
{v:7,t:"Agora, pois, devolve a mulher a seu marido, porque ele é profeta e orará por ti, e viverás; mas, se não a devolveres, sabe que certamente morrerás, tu e tudo o que é teu.",n:"Primeira vez que a palavra profeta aparece na Escritura, e é aplicada a Abraão; a função que se lhe atribui não é anunciar o futuro, mas interceder."},
{v:8,t:"Abimelec levantou-se de madrugada, chamou todos os seus servos e contou-lhes tudo isto; e os homens tiveram grande medo."},
{v:9,t:"Depois chamou Abraão e disse-lhe: Que nos fizeste? Em que pequei contra ti, para trazeres sobre mim e sobre o meu reino tamanho pecado? Fizeste comigo o que não se deve fazer.",n:"É um rei pagão quem dá a lição de moral ao patriarca. O livro põe a censura na boca de fora, e Abraão não tem grande resposta."},
{v:10,t:"E acrescentou Abimelec: Que tinhas em vista, para fazeres isso?"},
{v:11,t:"Respondeu Abraão: Pensei comigo: Certamente não há temor de Deus neste lugar, e me matarão por causa da minha mulher."},
{v:12,t:"E, de fato, ela é minha irmã, filha de meu pai, mas não filha de minha mãe; e veio a ser minha mulher."},
{v:13,t:"Quando Deus me fez andar errante, longe da casa de meu pai, eu disse a ela: Esta é a bondade que hás de fazer-me: em todo lugar aonde formos, dirás de mim que sou teu irmão."},
{v:14,t:"Então Abimelec tomou ovelhas, bois, servos e servas, e os deu a Abraão; e restituiu-lhe Sara, sua mulher,"},
{v:15,t:"e disse: Eis que a minha terra está diante de ti; habita onde melhor te parecer."},
{v:16,t:"E a Sara disse: Eis que dei mil moedas de prata a teu irmão; isto te servirá de reparação diante de todos os que estão contigo; e em tudo ficas justificada."},
{v:17,t:"Abraão orou a Deus, e Deus curou Abimelec, sua mulher e suas servas, e elas tiveram filhos;"},
{v:18,t:"porque o Senhor havia fechado todos os ventres da casa de Abimelec, por causa de Sara, mulher de Abraão."}
];

window.TEXTOS_SEED["genesis"][21] = [
{s:"O nascimento de Isaac"},
{v:1,t:"O Senhor visitou Sara, como dissera, e cumpriu nela o que prometera."},
{v:2,t:"Sara concebeu e deu à luz um filho a Abraão na sua velhice, no tempo que Deus lhe predissera."},
{v:3,t:"E Abraão deu ao filho que lhe nascera, que Sara lhe dera, o nome de Isaac;"},
{v:4,t:"e circuncidou Isaac, seu filho, aos oito dias, como Deus lhe ordenara."},
{v:5,t:"Abraão tinha cem anos quando lhe nasceu Isaac, seu filho."},
{v:6,t:"E Sara disse: Deus preparou-me um riso; todo o que o souber rirá comigo.",n:"O riso da descrença, no capítulo 18, torna-se aqui riso de festa. A mesma palavra serve para o escárnio e para a alegria, e o nome do menino guarda as duas."},
{v:7,t:"E acrescentou: Quem diria a Abraão que Sara amamentaria filhos? Pois dei-lhe um filho na sua velhice."},
{s:"Agar e Ismael despedidos"},
{v:8,t:"O menino cresceu e foi desmamado; e Abraão deu um grande banquete no dia em que Isaac foi desmamado."},
{v:9,t:"Sara viu que o filho que Agar, a egípcia, dera a Abraão brincava com Isaac, seu filho; e disse a Abraão:"},
{v:10,t:"Expulsa essa escrava e o filho dela, porque o filho da escrava não será herdeiro com Isaac, meu filho.",n:"São Paulo, na Carta aos Gálatas, lê alegoricamente as duas mulheres como as duas alianças, e cita esta frase. É preciso não esquecer o sentido primeiro: uma mulher manda pôr fora outra mulher e o filho dela, e o texto conta-o sem lhe passar a mão pela cabeça."},
{v:11,t:"Isto pareceu muito duro a Abraão, por causa de seu filho."},
{v:12,t:"Mas Deus lhe disse: Não te pareça duro por causa do menino e da tua escrava; atende a tudo o que Sara te disser, porque é por Isaac que a tua descendência será chamada."},
{v:13,t:"Mas também do filho da escrava farei uma nação, porque é tua descendência."},
{v:14,t:"Abraão levantou-se de manhã cedo, tomou pão e um odre de água e os deu a Agar, pondo-os sobre o ombro dela; e entregou-lhe o menino e despediu-a. Ela partiu e andou errante no deserto de Bersabeia."},
{v:15,t:"Acabada a água do odre, deitou o menino debaixo de um arbusto"},
{v:16,t:"e foi sentar-se em frente, à distância de um tiro de arco, dizendo: Não quero ver morrer o menino. E, sentada em frente, levantou a voz e chorou."},
{v:17,t:"Deus ouviu a voz do menino; e o anjo de Deus chamou do céu por Agar e lhe disse: Que tens, Agar? Não temas, porque Deus ouviu a voz do menino, no lugar onde está.",n:"Ismael quer dizer Deus ouve, e o nome cumpre-se aqui: Deus ouve o menino, a quem o texto não dá voz nenhuma. É a segunda vez que Agar encontra Deus no deserto."},
{v:18,t:"Levanta-te, toma o menino e segura-o pela mão, porque dele farei uma grande nação."},
{v:19,t:"E Deus abriu-lhe os olhos, e ela viu um poço de água; foi, encheu o odre e deu de beber ao menino."},
{v:20,t:"E Deus estava com o menino, que cresceu e habitou no deserto, e tornou-se archeiro."},
{v:21,t:"Habitou no deserto de Farã, e sua mãe tomou-lhe uma mulher da terra do Egito."},
{s:"A aliança em Bersabeia"},
{v:22,t:"Por aquele tempo Abimelec e Ficol, chefe do seu exército, disseram a Abraão: Deus está contigo em tudo o que fazes."},
{v:23,t:"Jura-me, pois, aqui por Deus que não me enganarás, nem a meus filhos, nem aos meus descendentes; mas, conforme a bondade que te fiz, assim farás comigo e à terra em que moraste como estrangeiro."},
{v:24,t:"E Abraão disse: Eu juro."},
{v:25,t:"Mas Abraão queixou-se a Abimelec por causa de um poço de água que os servos dele haviam tomado à força."},
{v:26,t:"Respondeu Abimelec: Não sei quem fez isso; tu não me avisaste, nem eu o ouvi senão hoje."},
{v:27,t:"Abraão tomou ovelhas e bois e os deu a Abimelec; e ambos fizeram aliança."},
{v:28,t:"E Abraão pôs à parte sete cordeiras do rebanho."},
{v:29,t:"Abimelec perguntou-lhe: Que significam estas sete cordeiras que puseste à parte?"},
{v:30,t:"Respondeu: Receberás da minha mão estas sete cordeiras, para me servirem de testemunho de que cavei este poço."},
{v:31,t:"Por isso se chamou aquele lugar Bersabeia, porque ali os dois juraram.",n:"Bersabeia pode ouvir-se como poço do juramento ou poço dos sete, e o relato brinca com as duas coisas: são sete cordeiras e é um juramento."},
{v:32,t:"Fizeram, pois, aliança em Bersabeia; e Abimelec e Ficol, chefe do seu exército, levantaram-se e voltaram para a terra dos filisteus."},
{v:33,t:"Abraão plantou uma tamargueira em Bersabeia e invocou ali o nome do Senhor, Deus eterno."},
{v:34,t:"E Abraão morou muito tempo como estrangeiro na terra dos filisteus."}
];

window.TEXTOS_SEED["genesis"][22] = [
{s:"O sacrifício de Isaac"},
{v:1,t:"Depois destas coisas, Deus pôs Abraão à prova e disse-lhe: Abraão! Ele respondeu: Eis-me aqui.",n:"A tradição judaica chama a este capítulo a Aqedá, a amarração. O texto avisa o leitor, logo na primeira linha, de que se trata de uma prova: Abraão não o sabe, e é essa diferença que faz o capítulo."},
{v:2,t:"E Deus disse: Toma teu filho, o teu único, a quem amas, Isaac, e vai à terra de Moriá; e oferece-o ali em holocausto, sobre um dos montes que eu te indicarei.",n:"A ordem é dada com uma lentidão cruel: teu filho, o teu único, a quem amas, Isaac. Moriá é, no segundo livro das Crônicas, o monte do templo em Jerusalém."},
{v:3,t:"Abraão levantou-se de manhã cedo, albardou o seu jumento e levou consigo dois servos e Isaac, seu filho. Rachou a lenha para o holocausto, e partiu para o lugar que Deus lhe indicara.",n:"Nenhuma palavra, nenhuma pergunta. Ele que discutira por Sodoma, que não é sua, cala-se agora pelo filho. O silêncio deste verso é o que os comentadores nunca acabaram de sondar."},
{v:4,t:"Ao terceiro dia, levantando os olhos, viu o lugar de longe;"},
{v:5,t:"e disse aos servos: Ficai aqui com o jumento; eu e o menino iremos até lá e, depois de adorarmos, voltaremos a vós.",n:"Voltaremos: no plural. Pode ser dissimulação para com os servos, ou pode ser o que a Carta aos Hebreus entendeu — que Abraão contava que Deus fosse capaz de ressuscitar."},
{v:6,t:"Abraão tomou a lenha do holocausto e a pôs sobre Isaac, seu filho; ele levava nas mãos o fogo e a faca. E foram ambos juntos."},
{v:7,t:"Isaac disse a Abraão, seu pai: Meu pai! Ele respondeu: Que queres, meu filho? E disse: Eis o fogo e a lenha; mas onde está o cordeiro para o holocausto?"},
{v:8,t:"Respondeu Abraão: Deus proverá para si o cordeiro do holocausto, meu filho. E foram ambos juntos.",n:"A frase e foram ambos juntos repete-se antes e depois da pergunta, e é a mesma nas duas vezes. Entre uma e outra passou tudo, e nada mudou no andar dos dois."},
{v:9,t:"Chegaram ao lugar que Deus lhe indicara, e ali Abraão edificou o altar e dispôs a lenha em cima; amarrou Isaac, seu filho, e o pôs sobre o altar, em cima da lenha."},
{v:10,t:"E Abraão estendeu a mão e tomou a faca, para imolar o filho."},
{v:11,t:"Mas o anjo do Senhor clamou-lhe do céu: Abraão, Abraão! Ele respondeu: Eis-me aqui."},
{v:12,t:"E disse: Não estendas a mão sobre o menino, nem lhe faças nada; agora sei que temes a Deus, pois não me recusaste o teu filho, o teu único."},
{v:13,t:"Abraão levantou os olhos e viu um carneiro preso pelos chifres num arbusto; foi, tomou o carneiro e ofereceu-o em holocausto, em lugar do filho.",n:"É o primeiro substituto da Escritura, e todo o sistema dos sacrifícios está em germe neste carneiro. O que o capítulo estabelece, de passagem, é que Deus não quer o filho — o sacrifício de crianças, que os povos vizinhos praticavam, fica aqui cortado pela raiz."},
{v:14,t:"E Abraão chamou àquele lugar: O Senhor provê. Por isso se diz até hoje: No monte o Senhor será visto."},
{s:"O juramento"},
{v:15,t:"O anjo do Senhor chamou Abraão do céu pela segunda vez,"},
{v:16,t:"e disse: Por mim mesmo jurei, diz o Senhor: porque fizeste isto e não me recusaste o teu filho, o teu único,",n:"Único lugar do Gênesis em que Deus jura por si mesmo, e a Carta aos Hebreus faz disso o argumento de que não havia ninguém maior por quem jurar."},
{v:17,t:"eu te abençoarei e multiplicarei a tua descendência como as estrelas do céu e como a areia na praia do mar; e a tua descendência possuirá as portas dos seus inimigos."},
{v:18,t:"E na tua descendência serão abençoadas todas as nações da terra, porque obedeceste à minha voz."},
{v:19,t:"Abraão voltou para junto dos seus servos, e levantaram-se e foram juntos para Bersabeia; e Abraão habitou em Bersabeia.",n:"Isaac não é nomeado no caminho de volta, e pai e filho não tornam a falar-se em toda a Escritura. O relato, que tanto insistira no foram ambos juntos, não diz que voltaram juntos."},
{s:"Os filhos de Nacor"},
{v:20,t:"Depois disto, foi dito a Abraão: Eis que também Melca deu filhos a Nacor, teu irmão:"},
{v:21,t:"Us, o primogênito, Buz, seu irmão, Camuel, pai de Aram,"},
{v:22,t:"Cased, Azau, Feldas, Jedlaf"},
{v:23,t:"e Batuel, do qual nasceu Rebeca. Estes oito deu Melca a Nacor, irmão de Abraão.",n:"A genealogia parece deslocada, mas é posta aqui por causa do último nome: acabado o capítulo do filho quase perdido, anuncia-se a mulher que há de continuar a promessa."},
{v:24,t:"A sua concubina, chamada Reuma, deu à luz Tabee, Gaam, Taas e Maaca."}
];

window.TEXTOS_SEED["genesis"][23] = [
{s:"A morte de Sara"},
{v:1,t:"Sara viveu cento e vinte e sete anos.",n:"Única mulher da Escritura cuja idade se registra ao morrer."},
{v:2,t:"E morreu em Cariat-Arbé, que é Hebron, na terra de Canaã; e Abraão veio fazer o pranto por Sara e chorá-la."},
{v:3,t:"Levantando-se de junto do seu morto, Abraão falou aos filhos de Het, dizendo:"},
{v:4,t:"Sou estrangeiro e forasteiro entre vós; dai-me entre vós uma propriedade para sepultura, para que eu sepulte o meu morto.",n:"Estrangeiro e forasteiro: a quem foi prometida a terra inteira não pertence, nesta altura, um palmo dela. A Carta aos Hebreus fará desta condição o retrato da fé."},
{v:5,t:"Os filhos de Het responderam:"},
{v:6,t:"Ouve-nos, senhor: és entre nós um príncipe de Deus; sepulta o teu morto no melhor dos nossos sepulcros; nenhum de nós te negará o seu sepulcro, para nele sepultares o teu morto."},
{v:7,t:"Abraão levantou-se e inclinou-se diante do povo da terra, os filhos de Het,"},
{v:8,t:"e disse-lhes: Se é da vossa vontade que eu sepulte o meu morto, ouvi-me e intercedei por mim junto de Efron, filho de Seor,"},
{v:9,t:"para que me dê a caverna de Macpela, que é dele e está no extremo do seu campo. Que ma ceda por todo o seu valor, diante de vós, como propriedade para sepultura."},
{v:10,t:"Ora, Efron estava sentado no meio dos filhos de Het; e Efron, o heteu, respondeu a Abraão, ouvindo-o todos os filhos de Het, todos os que entravam pela porta da cidade, e disse:"},
{v:11,t:"Não, meu senhor; escuta-me: dou-te o campo e dou-te a caverna que nele está, na presença dos filhos do meu povo; sepulta o teu morto."},
{v:12,t:"Abraão inclinou-se diante do povo da terra"},
{v:13,t:"e disse a Efron, ouvindo-o o povo da terra: Peço-te que me escutes: pagarei o preço do campo; aceita-o de mim, e ali sepultarei o meu morto.",n:"O regateio segue o cerimonial oriental: quem oferece de graça espera que se pague, e quem paga insiste em pagar. Abraão quer um título e não um favor, porque um favor se desfaz."},
{v:14,t:"Efron respondeu a Abraão:"},
{v:15,t:"Meu senhor, escuta-me: uma terra de quatrocentos siclos de prata, que é isso entre mim e ti? Sepulta o teu morto."},
{v:16,t:"Abraão atendeu a Efron e pesou-lhe a prata que ele pedira, ouvindo-o os filhos de Het: quatrocentos siclos de prata, corrente entre os mercadores.",n:"O preço é alto, e o narrador não o comenta. O que lhe importa é a fórmula jurídica dos versos seguintes, que descreve a compra como se copiasse uma escritura."},
{v:17,t:"Assim ficou confirmado o campo de Efron, em Macpela, defronte de Mambré, o campo e a caverna que nele havia, e todas as árvores que estavam no campo, em todo o seu contorno,"},
{v:18,t:"como propriedade de Abraão, na presença dos filhos de Het e de todos os que entravam pela porta da cidade."},
{v:19,t:"Depois disso, Abraão sepultou Sara, sua mulher, na caverna do campo de Macpela, defronte de Mambré, que é Hebron, na terra de Canaã."},
{v:20,t:"E o campo, com a caverna que nele havia, foi confirmado a Abraão pelos filhos de Het, como propriedade para sepultura.",n:"É o primeiro pedaço de Canaã que passa a ser de Abraão, e é um túmulo. Ali serão enterrados Abraão, Isaac, Rebeca, Lia e Jacó; a mesquita de Hebron guarda hoje o lugar."}
];

window.TEXTOS_SEED["genesis"][24] = [
{s:"O servo enviado"},
{v:1,t:"Abraão era já velho, de idade avançada; e o Senhor o abençoara em tudo.",n:"O capítulo mais longo do Gênesis, e é inteiro sobre um casamento arranjado por um criado sem nome. O narrador conta duas vezes a mesma história, primeiro como acontece e depois pela boca do servo, o que é o seu modo de a saborear."},
{v:2,t:"E disse Abraão ao servo mais velho da sua casa, que administrava tudo o que tinha: Põe a tua mão debaixo da minha coxa,"},
{v:3,t:"para que eu te faça jurar pelo Senhor, Deus do céu e Deus da terra, que não tomarás para meu filho mulher dentre as filhas dos cananeus, no meio dos quais habito;"},
{v:4,t:"mas irás à minha terra e à minha parentela, e ali tomarás mulher para meu filho Isaac."},
{v:5,t:"Respondeu o servo: E se a mulher não quiser vir comigo a esta terra? Devo então levar teu filho de volta à terra donde saíste?"},
{v:6,t:"Disse-lhe Abraão: Guarda-te de levares para lá o meu filho.",n:"Nem que a promessa pareça falhar: voltar atrás é o que não se faz. A viagem de Abraão foi só de ida."},
{v:7,t:"O Senhor, Deus do céu, que me tirou da casa de meu pai e da terra do meu nascimento, que me falou e me jurou, dizendo: À tua descendência darei esta terra, ele enviará o seu anjo adiante de ti, e dali tomarás mulher para meu filho."},
{v:8,t:"Se a mulher não quiser seguir-te, ficarás desobrigado deste juramento; somente não leves para lá o meu filho."},
{v:9,t:"O servo pôs a mão debaixo da coxa de Abraão, seu senhor, e jurou-lhe sobre isso."},
{s:"Junto ao poço"},
{v:10,t:"O servo tomou dez camelos do rebanho do seu senhor e partiu, levando consigo do que havia de melhor entre os bens dele; e foi para Aram-Naaraim, à cidade de Nacor."},
{v:11,t:"Fez ajoelhar os camelos fora da cidade, junto a um poço de água, ao anoitecer, à hora em que as mulheres costumam sair a tirar água;"},
{v:12,t:"e disse: Senhor, Deus de meu senhor Abraão, dá-me hoje bom encontro e usa de bondade para com o meu senhor Abraão."},
{v:13,t:"Eis que estou junto à fonte de água, e as filhas dos homens desta cidade saem a tirar água."},
{v:14,t:"Aconteça, pois, que a moça a quem eu disser: Inclina o teu cântaro, para eu beber, e que me responder: Bebe, e também darei de beber aos teus camelos, essa seja a que destinaste ao teu servo Isaac; e por isso conhecerei que usaste de bondade para com o meu senhor.",n:"O sinal que o servo pede não é prodígio nenhum: é um gesto de generosidade a mais do que o pedido. Dez camelos sedentos bebem muitos baldes, e quem se oferece para tirá-los está a oferecer uma hora de trabalho a um desconhecido."},
{v:15,t:"Ainda não acabara de falar consigo mesmo, e eis que saía Rebeca, filha de Batuel, filho de Melca, mulher de Nacor, irmão de Abraão, com o cântaro ao ombro;"},
{v:16,t:"a moça era muito formosa, virgem, e nenhum homem a conhecera. Desceu à fonte, encheu o cântaro e subiu."},
{v:17,t:"O servo correu ao seu encontro e disse: Dá-me, por favor, um pouco de água do teu cântaro."},
{v:18,t:"Ela respondeu: Bebe, meu senhor. E depressa baixou o cântaro sobre o braço e deu-lhe de beber."},
{v:19,t:"Quando acabou de lhe dar de beber, disse: Também para os teus camelos tirarei água, até que todos bebam."},
{v:20,t:"E, esvaziando depressa o cântaro no bebedouro, correu outra vez ao poço a tirar água, e tirou para todos os camelos."},
{v:21,t:"O homem contemplava-a em silêncio, querendo saber se o Senhor tinha ou não abençoado a sua viagem."},
{v:22,t:"Depois que os camelos acabaram de beber, o homem tomou um pendente de ouro, do peso de meio siclo, e dois braceletes para os pulsos dela, do peso de dez siclos de ouro;"},
{v:23,t:"e disse: De quem és filha? Dize-me, por favor. Há na casa de teu pai lugar para passarmos a noite?"},
{v:24,t:"Ela respondeu: Sou filha de Batuel, filho de Melca, que ela deu a Nacor."},
{v:25,t:"E acrescentou: Temos palha e forragem em abundância, e também lugar para passar a noite."},
{v:26,t:"Então o homem inclinou-se e adorou o Senhor,"},
{v:27,t:"dizendo: Bendito seja o Senhor, Deus de meu senhor Abraão, que não retirou a sua bondade e a sua fidelidade do meu senhor, e me conduziu pelo caminho certo à casa dos parentes do meu senhor."},
{s:"Em casa de Labão"},
{v:28,t:"A moça correu e contou tudo isto em casa de sua mãe."},
{v:29,t:"Rebeca tinha um irmão chamado Labão, que saiu depressa ao encontro do homem, junto à fonte."},
{v:30,t:"Pois, tendo visto o pendente e os braceletes nos pulsos de sua irmã, e ouvido as palavras de Rebeca, que contava: Assim me falou o homem, veio ter com ele, que estava junto aos camelos, ao pé da fonte,",n:"O narrador deixa ver o que move Labão: primeiro viu o ouro, depois ouviu a história. É um traço que o capítulo 31 há de confirmar largamente."},
{v:31,t:"e disse-lhe: Entra, bendito do Senhor; por que ficas aí fora? Já preparei a casa e o lugar para os camelos."},
{v:32,t:"O homem entrou em casa, e Labão desatou os camelos, deu-lhes palha e forragem, e água para lavar os pés dele e dos homens que o acompanhavam."},
{v:33,t:"Depois puseram-lhe comida diante; mas ele disse: Não comerei enquanto não disser o que tenho a dizer. Responderam: Fala."},
{v:34,t:"E disse: Eu sou servo de Abraão."},
{v:35,t:"O Senhor abençoou muito o meu senhor, que se tornou grande; deu-lhe ovelhas e bois, prata e ouro, servos e servas, camelos e jumentos."},
{v:36,t:"E Sara, mulher do meu senhor, deu-lhe um filho na velhice, ao qual ele deu tudo o que tem."},
{v:37,t:"O meu senhor fez-me jurar, dizendo: Não tomarás para meu filho mulher dentre as filhas dos cananeus, em cuja terra habito;"},
{v:38,t:"mas irás à casa de meu pai e à minha parentela, e ali tomarás mulher para meu filho."},
{v:39,t:"Eu disse ao meu senhor: E se a mulher não quiser vir comigo?"},
{v:40,t:"Ele respondeu: O Senhor, em cuja presença ando, enviará o seu anjo contigo e fará prosperar a tua viagem; e tomarás mulher para meu filho da minha parentela e da casa de meu pai."},
{v:41,t:"Ficarás livre do meu juramento quando fores aos meus parentes; e, se não ta derem, estarás livre do meu juramento."},
{v:42,t:"Cheguei hoje à fonte e disse: Senhor, Deus de meu senhor Abraão, se queres fazer prosperar o caminho que trilho,"},
{v:43,t:"eis que estou junto à fonte de água; a moça que sair a tirar água, e a quem eu disser: Dá-me um pouco de água a beber do teu cântaro,"},
{v:44,t:"e me responder: Bebe tu, e também tirarei água para os teus camelos, essa seja a mulher que o Senhor destinou ao filho do meu senhor."},
{v:45,t:"Ainda não acabara de falar no meu coração, e eis que saía Rebeca, com o cântaro ao ombro; desceu à fonte e tirou água. E eu lhe disse: Dá-me de beber, por favor."},
{v:46,t:"Ela depressa baixou o cântaro do ombro e disse: Bebe tu, e também darei de beber aos teus camelos. Bebi, e ela deu de beber aos camelos."},
{v:47,t:"Perguntei-lhe: De quem és filha? Respondeu: Filha de Batuel, filho de Nacor, que Melca lhe deu. Então pus o pendente no seu nariz e os braceletes nos seus pulsos."},
{v:48,t:"E inclinei-me e adorei o Senhor, e bendisse o Senhor, Deus de meu senhor Abraão, que me conduziu pelo caminho certo para tomar a filha do parente do meu senhor para o filho dele."},
{v:49,t:"Agora, pois, se quereis usar de bondade e fidelidade para com o meu senhor, dizei-mo; e, se não, dizei-mo também, para que eu me volte para a direita ou para a esquerda."},
{s:"Rebeca parte"},
{v:50,t:"Responderam Labão e Batuel: Do Senhor procedeu isto; nada podemos dizer-te, nem bem nem mal."},
{v:51,t:"Eis Rebeca diante de ti: toma-a e vai; e seja ela a mulher do filho do teu senhor, como disse o Senhor."},
{v:52,t:"Quando o servo de Abraão ouviu as palavras deles, prostrou-se em terra diante do Senhor."},
{v:53,t:"Depois tirou objetos de prata e de ouro, e vestidos, e deu-os a Rebeca; e deu também presentes valiosos a seu irmão e a sua mãe."},
{v:54,t:"Comeram e beberam, ele e os homens que o acompanhavam, e passaram a noite ali. Levantando-se de manhã, o servo disse: Deixai-me ir ao meu senhor."},
{v:55,t:"O irmão e a mãe dela responderam: Fique a moça conosco ao menos uns dez dias, e depois irá."},
{v:56,t:"Mas ele disse: Não me detenhais, pois o Senhor fez prosperar o meu caminho; deixai-me partir para o meu senhor."},
{v:57,t:"Disseram: Chamemos a moça e perguntemos-lhe o que ela quer."},
{v:58,t:"Chamaram Rebeca e perguntaram-lhe: Queres ir com este homem? Ela respondeu: Irei.",n:"A palavra é de uma só sílaba no hebraico, e é a mesma com que Abraão saiu de Harã. A esta mulher se pergunta, e ela responde por si: o capítulo inteiro, com toda a sua cerimônia, cabe nesta resposta."},
{v:59,t:"Então deixaram ir Rebeca, sua irmã, e a sua ama, e o servo de Abraão e os seus homens."},
{v:60,l:["E abençoaram Rebeca, dizendo-lhe:","Irmã nossa, sejas tu mãe de milhares de milhares,","e possua a tua descendência","as portas dos seus inimigos."]},
{v:61,t:"Rebeca levantou-se com as suas servas e, montadas nos camelos, seguiram o homem; e o servo tomou Rebeca e partiu."},
{s:"O encontro com Isaac"},
{v:62,t:"Isaac tinha voltado do poço de Lacai-Roi, pois habitava na terra do Negueb."},
{v:63,t:"E saíra ao campo, ao cair da tarde, para meditar; e, levantando os olhos, viu que vinham camelos.",n:"O verbo é raro e obscuro: uns entendem meditar, outros passear, outros lamentar-se. Vem logo depois da morte de Sara, e o fim do capítulo diz que Isaac se consolou da mãe."},
{v:64,t:"Também Rebeca levantou os olhos e viu Isaac; e desceu do camelo,"},
{v:65,t:"e perguntou ao servo: Quem é aquele homem que vem pelo campo ao nosso encontro? Respondeu o servo: É o meu senhor. E ela tomou depressa o véu e cobriu-se."},
{v:66,t:"O servo contou a Isaac tudo o que fizera."},
{v:67,t:"Isaac introduziu Rebeca na tenda de Sara, sua mãe; tomou-a por mulher, e amou-a; e assim se consolou Isaac da morte de sua mãe.",n:"Única vez que a Escritura diz de um patriarca, com todas as letras, que amou a mulher com quem casou; e é o único dos três que não terá outra."}
];

window.TEXTOS_SEED["genesis"][25] = [
{s:"Os filhos de Quetura"},
{v:1,t:"Abraão tomou outra mulher, chamada Quetura,"},
{v:2,t:"que lhe deu Zamran, Jecsan, Madan, Madiã, Jesboc e Sué."},
{v:3,t:"Jecsan gerou Sabá e Dedan; os filhos de Dedan foram os assurim, os latusim e os loomim."},
{v:4,t:"Os filhos de Madiã foram Efa, Ofer, Henoc, Abida e Eldaa. Todos estes são filhos de Quetura.",n:"São os povos do deserto árabe, e Madiã é aquele em cuja terra Moisés há de guardar rebanhos. O livro faz questão de lhes dar parentesco com Abraão."},
{v:5,t:"Abraão deu tudo o que possuía a Isaac;"},
{v:6,t:"aos filhos das suas concubinas deu presentes e, ainda em vida, apartou-os de Isaac, seu filho, mandando-os para o oriente."},
{s:"A morte de Abraão"},
{v:7,t:"Os dias da vida de Abraão foram cento e setenta e cinco anos."},
{v:8,t:"E Abraão expirou e morreu numa boa velhice, idoso e cheio de dias; e foi reunido ao seu povo.",n:"Reunido ao seu povo é fórmula anterior a qualquer doutrina sobre a outra vida: diz apenas que vai ter com os que morreram antes. A esperança da ressurreição só se formulará muito mais tarde."},
{v:9,t:"Isaac e Ismael, seus filhos, sepultaram-no na caverna de Macpela, no campo de Efron, filho de Seor, o heteu, defronte de Mambré,",n:"Os dois filhos, o da promessa e o da escrava, separados desde o capítulo 21, aparecem lado a lado no enterro do pai. É tudo o que o livro diz a respeito, e basta."},
{v:10,t:"campo que Abraão comprara aos filhos de Het. Ali foram sepultados Abraão e Sara, sua mulher."},
{v:11,t:"Depois da morte de Abraão, Deus abençoou Isaac, seu filho; e Isaac habitava junto ao poço de Lacai-Roi."},
{s:"Os filhos de Ismael"},
{v:12,t:"Estas são as gerações de Ismael, filho de Abraão, que Agar, a egípcia, escrava de Sara, lhe deu."},
{v:13,t:"Estes são os nomes dos filhos de Ismael, pelos seus nomes e gerações: o primogênito de Ismael foi Nabaiot; depois Cedar, Adbeel, Mabsam,"},
{v:14,t:"Masma, Duma, Massa,"},
{v:15,t:"Hadad, Tema, Jetur, Nafis e Cedma."},
{v:16,t:"Estes são os filhos de Ismael, e estes os seus nomes, pelas suas aldeias e acampamentos: doze príncipes, segundo as suas tribos.",n:"Doze príncipes, como as doze tribos de Israel. A promessa feita a Agar no deserto cumpre-se na mesma medida da que foi feita a Sara."},
{v:17,t:"Os anos da vida de Ismael foram cento e trinta e sete; e expirou e morreu, e foi reunido ao seu povo."},
{v:18,t:"Os seus descendentes habitaram desde Havilá até Sur, que está defronte do Egito, na direção da Assíria; e ele se estabeleceu defronte de todos os seus irmãos."},
{s:"Esaú e Jacó"},
{v:19,t:"Estas são as gerações de Isaac, filho de Abraão: Abraão gerou Isaac."},
{v:20,t:"Isaac tinha quarenta anos quando tomou por mulher Rebeca, filha de Batuel, o arameu de Padã-Aram, irmã de Labão, o arameu."},
{v:21,t:"Isaac suplicou ao Senhor pela sua mulher, porque ela era estéril; e o Senhor ouviu-o, e Rebeca concebeu.",n:"Terceira geração, terceira esterilidade. O livro insiste: a descendência prometida não vem por via natural, e há de ser sempre dada."},
{v:22,t:"Mas os filhos lutavam no seu ventre; e ela disse: Se é assim, por que sou eu assim? E foi consultar o Senhor."},
{v:23,l:["O Senhor respondeu-lhe:","Duas nações há no teu ventre,","e dois povos se dividirão desde as tuas entranhas;","um povo será mais forte que o outro,","e o mais velho servirá ao mais novo."],n:"São Paulo cita este oráculo na Carta aos Romanos, notando que foi dado antes de os gêmeos nascerem e de terem feito bem ou mal. O mais velho servirá ao mais novo é o que o Gênesis faz acontecer quase sempre: Isaac, Jacó, José, Efraim."},
{v:24,t:"Chegado o tempo de dar à luz, eis que havia gêmeos no seu ventre."},
{v:25,t:"O primeiro que saiu era ruivo e todo peludo como uma capa; e chamaram-lhe Esaú. Depois saiu o seu irmão, segurando com a mão o calcanhar de Esaú; e por isso lhe puseram o nome de Jacó.",n:"Jacó soa como calcanhar e como suplantar; o nome é, desde o berço, uma acusação, e Esaú há de usá-la no capítulo 27. Esaú é ouvido como peludo, e o ruivo prepara o apelido de Edom."},
{v:26,t:"Isaac tinha sessenta anos quando eles nasceram."},
{s:"O direito de primogenitura vendido"},
{v:27,t:"Os meninos cresceram; e Esaú tornou-se hábil caçador, homem do campo, enquanto Jacó era homem tranquilo, que ficava nas tendas."},
{v:28,t:"Isaac amava Esaú, porque comia da sua caça; mas Rebeca amava Jacó.",n:"Em meia linha está armada a tragédia dos dois capítulos seguintes: cada pai tem o seu preferido, e a casa está partida ao meio antes de acontecer coisa alguma."},
{v:29,t:"Certa vez Jacó preparava um guisado, quando Esaú voltou do campo, exausto,"},
{v:30,t:"e disse a Jacó: Dá-me de comer desse vermelho, desse vermelho aí, porque estou exausto. Por isso se chamou o seu nome Edom, isto é, Vermelho.",n:"Esaú nem sabe o nome do que está a comer: diz duas vezes desse vermelho. O narrador põe-lhe na boca a pressa do apetite, e do apetite lhe tira o nome do povo inteiro."},
{v:31,t:"Disse Jacó: Vende-me hoje o teu direito de primogenitura."},
{v:32,t:"Respondeu Esaú: Estou a morrer; de que me serve a primogenitura?"},
{v:33,t:"Disse Jacó: Jura-me hoje. E Esaú jurou-lhe, e vendeu a Jacó a sua primogenitura."},
{v:34,t:"Então Jacó deu a Esaú pão e o guisado de lentilhas; ele comeu e bebeu, levantou-se e foi-se embora. Assim desprezou Esaú a primogenitura.",n:"Cinco verbos secos, um atrás do outro, e o juízo final numa frase. A Carta aos Hebreus há de citar o episódio como exemplo de quem vende por uma refeição o que não se compra de volta."}
];

window.TEXTOS_SEED["genesis"][26] = [
{s:"Isaac em Gerara"},
{v:1,t:"Houve fome na terra, além da primeira fome que houvera nos dias de Abraão; e Isaac foi ter com Abimelec, rei dos filisteus, em Gerara."},
{v:2,t:"O Senhor apareceu-lhe e disse: Não desças ao Egito; habita na terra que eu te disser."},
{v:3,t:"Mora nela como estrangeiro, e eu serei contigo e te abençoarei; porque a ti e à tua descendência darei todas estas terras, e cumprirei o juramento que fiz a Abraão, teu pai."},
{v:4,t:"Multiplicarei a tua descendência como as estrelas do céu, e lhe darei todas estas terras; e na tua descendência serão abençoadas todas as nações da terra,"},
{v:5,t:"porque Abraão obedeceu à minha voz e guardou os meus preceitos, os meus mandamentos, os meus estatutos e as minhas leis.",n:"Isaac é o único patriarca que não recebe promessa por si: tudo o que ouve é por causa do pai. De toda a sua vida o livro conta apenas este capítulo."},
{v:6,t:"Isaac ficou, pois, em Gerara."},
{v:7,t:"Quando os homens do lugar lhe perguntaram pela mulher, respondeu: É minha irmã; porque teve medo de dizer que era sua mulher, pensando: Para que não me matem por causa dela, pois é formosa."},
{v:8,t:"Passados muitos dias, e morando ele ali, Abimelec, rei dos filisteus, olhou pela janela e viu Isaac acariciando Rebeca, sua mulher."},
{v:9,t:"Chamou-o e disse: É evidente que ela é tua mulher; por que disseste: É minha irmã? Respondeu Isaac: Temi morrer por causa dela."},
{v:10,t:"E disse Abimelec: Que é isto que nos fizeste? Por pouco algum do povo se teria deitado com tua mulher, e terias trazido culpa sobre nós."},
{v:11,t:"E Abimelec ordenou a todo o povo: Quem tocar neste homem ou na sua mulher será morto."},
{s:"Os poços"},
{v:12,t:"Isaac semeou naquela terra e colheu, naquele ano, o cêntuplo; e o Senhor o abençoou."},
{v:13,t:"O homem enriqueceu, e foi prosperando cada vez mais, até se tornar muito poderoso;"},
{v:14,t:"teve rebanhos de ovelhas, manadas de bois e muita criadagem. Por isso os filisteus o invejaram,"},
{v:15,t:"e entulharam de terra todos os poços que os servos de seu pai tinham cavado nos dias de Abraão, seu pai.",n:"Tapar um poço, no deserto, é declarar guerra sem a fazer. O capítulo inteiro é uma disputa por água, contada com a paciência de quem sabe que dela depende tudo."},
{v:16,t:"E Abimelec disse a Isaac: Aparta-te de nós, porque te tornaste muito mais poderoso do que nós."},
{v:17,t:"Isaac partiu dali, acampou no vale de Gerara e ali habitou."},
{v:18,t:"Tornou a abrir os poços de água que se tinham cavado nos dias de Abraão, seu pai, e que os filisteus haviam entulhado depois da morte dele; e deu-lhes os mesmos nomes que seu pai lhes dera."},
{v:19,t:"Os servos de Isaac cavaram no vale e acharam ali um poço de água viva."},
{v:20,t:"Mas os pastores de Gerara contenderam com os pastores de Isaac, dizendo: A água é nossa. Por isso chamou àquele poço Esec, isto é, Contenda, porque contenderam com ele."},
{v:21,t:"Cavaram outro poço, e também por causa dele brigaram; e chamou-lhe Sitna, isto é, Inimizade."},
{v:22,t:"Partindo dali, cavou outro poço, e por esse não contenderam; e chamou-lhe Roobot, isto é, Largueza, dizendo: Agora o Senhor nos deu lugar largo, e havemos de crescer na terra.",n:"Isaac não briga nenhuma vez: cede o poço, muda de sítio e cava outro. O único patriarca sem façanhas é também o único que não deixa inimigo atrás de si."},
{v:23,t:"Dali subiu a Bersabeia."},
{v:24,t:"E o Senhor apareceu-lhe naquela noite e disse: Eu sou o Deus de Abraão, teu pai. Não temas, porque eu sou contigo; eu te abençoarei e multiplicarei a tua descendência, por amor de Abraão, meu servo."},
{v:25,t:"Isaac edificou ali um altar, invocou o nome do Senhor e armou ali a sua tenda; e os seus servos cavaram ali um poço."},
{s:"A aliança com Abimelec"},
{v:26,t:"Abimelec veio ter com ele, de Gerara, com Ocozat, seu amigo, e Ficol, chefe do seu exército."},
{v:27,t:"Isaac disse-lhes: Por que viestes a mim, vós que me odiais e me expulsastes do vosso meio?"},
{v:28,t:"Responderam: Vimos claramente que o Senhor é contigo, e por isso dissemos: Haja juramento entre nós e ti, e façamos aliança contigo,"},
{v:29,t:"para que não nos faças mal, como nós não te tocamos e só te fizemos bem, e te despedimos em paz. Tu és agora o bendito do Senhor."},
{v:30,t:"Isaac fez-lhes um banquete, e comeram e beberam."},
{v:31,t:"De manhã cedo levantaram-se e juraram um ao outro; e Isaac despediu-os, e partiram dele em paz."},
{v:32,t:"Naquele mesmo dia vieram os servos de Isaac dar-lhe notícia do poço que tinham cavado, dizendo: Achamos água."},
{v:33,t:"E ele chamou-lhe Sabé; por isso o nome da cidade é Bersabeia, até ao dia de hoje."},
{v:34,t:"Esaú, aos quarenta anos, tomou por mulheres Judit, filha de Beeri, o heteu, e Basemat, filha de Elon, o heteu;"},
{v:35,t:"e ambas foram amargura de espírito para Isaac e Rebeca.",n:"O verso prepara o fim do capítulo 27, em que Rebeca usará justamente este pretexto para mandar Jacó embora. Nada no Gênesis se diz por dizer."}
];

window.TEXTOS_SEED["genesis"][27] = [
{s:"A bênção roubada"},
{v:1,t:"Isaac envelheceu, e os seus olhos escureceram, de modo que não podia ver. Chamou Esaú, seu filho mais velho, e disse-lhe: Meu filho! Ele respondeu: Eis-me aqui."},
{v:2,t:"E o pai disse: Vês que estou velho e não sei o dia da minha morte."},
{v:3,t:"Toma, pois, as tuas armas, a aljava e o arco, sai ao campo e caça-me alguma coisa;"},
{v:4,t:"faze-me um guisado como eu gosto, traze-mo e eu comerei, para que a minha alma te abençoe antes que eu morra.",n:"A bênção do pai, no mundo antigo, tinha força de testamento e não se podia revogar. O capítulo inteiro se move dentro dessa convicção: dita a palavra, está feito."},
{v:5,t:"Rebeca escutava enquanto Isaac falava a Esaú, seu filho. E Esaú saiu ao campo, para caçar e trazer a caça."},
{v:6,t:"Então Rebeca disse a Jacó, seu filho: Eis que ouvi teu pai falar a Esaú, teu irmão, dizendo:"},
{v:7,t:"Traze-me caça e faze-me um guisado, para que eu coma e te abençoe diante do Senhor antes de morrer."},
{v:8,t:"Agora, pois, meu filho, ouve a minha voz no que te ordeno:"},
{v:9,t:"vai ao rebanho e traze-me dois bons cabritos; eu farei deles um guisado para teu pai, como ele gosta;"},
{v:10,t:"tu o levarás a teu pai, para que coma e te abençoe antes de morrer."},
{v:11,t:"Respondeu Jacó a Rebeca, sua mãe: Esaú, meu irmão, é homem peludo, e eu sou homem liso."},
{v:12,t:"Se meu pai me apalpar e perceber, serei aos olhos dele como quem zomba, e atrairei sobre mim maldição em vez de bênção.",n:"A objeção de Jacó não é moral: é o medo de ser apanhado. E a mãe responde no mesmo registro, assumindo a maldição. Nenhum dos dois discute se está certo."},
{v:13,t:"Disse-lhe a mãe: Caia sobre mim essa maldição, meu filho; ouve somente a minha voz e vai buscar o que eu disse."},
{v:14,t:"Ele foi, tomou-os e trouxe-os à mãe; e ela fez um guisado, como o pai dele gostava."},
{v:15,t:"Depois tomou as melhores roupas de Esaú, o filho mais velho, que tinha em casa, e vestiu com elas Jacó, o filho mais novo;"},
{v:16,t:"e com as peles dos cabritos cobriu-lhe as mãos e a parte lisa do pescoço."},
{v:17,t:"E pôs nas mãos de Jacó, seu filho, o guisado e o pão que tinha feito."},
{v:18,t:"Ele foi ter com o pai e disse: Meu pai! Respondeu: Estou aqui; quem és tu, meu filho?"},
{v:19,t:"Disse Jacó ao pai: Sou Esaú, teu primogênito; fiz como me ordenaste. Levanta-te, senta-te e come da minha caça, para que a tua alma me abençoe.",n:"A mentira é dita sem rodeios, e ainda invoca o nome de Deus no verso seguinte. O livro não a atenua; e Jacó há de pagá-la, enganado por Labão com a troca de uma filha pela outra, e depois pelos próprios filhos com a túnica de José."},
{v:20,t:"Isaac disse ao filho: Como a achaste tão depressa, meu filho? Respondeu: Porque o Senhor teu Deus ma deparou."},
{v:21,t:"Disse Isaac a Jacó: Chega-te, para que eu te apalpe, meu filho, e veja se és mesmo meu filho Esaú."},
{v:22,t:"Jacó chegou-se a Isaac, seu pai, que o apalpou e disse: A voz é a voz de Jacó, mas as mãos são as mãos de Esaú."},
{v:23,t:"E não o reconheceu, porque as suas mãos estavam peludas como as do irmão; e abençoou-o."},
{v:24,t:"E disse: És tu mesmo meu filho Esaú? Respondeu: Sou."},
{v:25,t:"E disse: Traze-me, e comerei da caça de meu filho, para que a minha alma te abençoe. Jacó trouxe-lhe, e ele comeu; trouxe-lhe também vinho, e bebeu."},
{v:26,t:"Então Isaac, seu pai, disse-lhe: Chega-te e beija-me, meu filho."},
{v:27,l:["Jacó chegou-se e beijou-o.","Isaac sentiu o cheiro das suas roupas","e abençoou-o, dizendo:","Eis que o cheiro de meu filho","é como o cheiro de um campo","que o Senhor abençoou."]},
{v:28,l:["Deus te dê do orvalho do céu","e da fertilidade da terra,","e abundância de trigo e de vinho."]},
{v:29,l:["Sirvam-te os povos","e prostrem-se diante de ti as nações;","sê senhor de teus irmãos,","e curvem-se diante de ti os filhos de tua mãe.","Maldito seja quem te amaldiçoar,","e bendito quem te abençoar!"],n:"A última linha repete a promessa feita a Abraão no capítulo 12. A bênção arrancada por fraude é, na sua matéria, a mesma que Deus dera de graça: o livro deixa a estranheza de pé, sem a explicar."},
{s:"Abençoa-me também a mim"},
{v:30,t:"Mal Isaac acabara de abençoar Jacó, e apenas Jacó saíra da presença de Isaac, seu pai, chegou Esaú, seu irmão, da sua caçada;"},
{v:31,t:"e também ele fez um guisado e levou-o ao pai, dizendo: Levanta-te, meu pai, e come da caça de teu filho, para que a tua alma me abençoe."},
{v:32,t:"Disse-lhe Isaac, seu pai: Quem és tu? Respondeu: Sou teu filho, o teu primogênito, Esaú."},
{v:33,t:"Isaac estremeceu com um tremor muito grande e disse: Quem é, pois, o que apanhou a caça e ma trouxe? Eu comi de tudo antes que viesses, e abençoei-o; e abençoado será!",n:"O estremecimento de Isaac é o momento em que ele percebe tudo — a fraude do filho, a mão da mulher, e que a palavra já saiu. E a sua conclusão não é desfazer: é confirmar."},
{v:34,t:"Ao ouvir as palavras do pai, Esaú soltou um grito altíssimo e amaríssimo, e disse ao pai: Abençoa-me também a mim, meu pai!"},
{v:35,t:"Ele respondeu: Veio o teu irmão com astúcia e tomou a tua bênção."},
{v:36,t:"E Esaú disse: Com razão se chama Jacó, pois já duas vezes me suplantou: tirou-me a primogenitura, e agora me tirou a bênção. E perguntou: Não reservaste bênção para mim?"},
{v:37,t:"Respondeu Isaac: Eis que o constituí teu senhor e lhe dei todos os seus irmãos por servos; sustentei-o com trigo e vinho. Que poderei, pois, fazer por ti, meu filho?"},
{v:38,t:"Disse Esaú ao pai: Tens uma só bênção, meu pai? Abençoa-me também a mim! E, chorando em alta voz,",n:"A Carta aos Hebreus recorda estas lágrimas, dizendo que Esaú não achou lugar para arrependimento, embora o procurasse com lágrimas. É das páginas mais amargas do livro."},
{v:39,l:["Isaac, seu pai, respondeu-lhe:","Longe da fertilidade da terra","será a tua morada,","e longe do orvalho que desce do céu."]},
{v:40,l:["Da tua espada viverás","e a teu irmão servirás;","mas virá o tempo em que te revoltarás","e sacudirás o seu jugo do teu pescoço."],n:"Edom foi vassalo de Judá e libertou-se no reinado de Jorão, como conta o livro dos Reis. O oráculo é lido, desde a antiguidade, à luz dessa história."},
{s:"A fuga de Jacó"},
{v:41,t:"Esaú odiou Jacó por causa da bênção com que o pai o abençoara, e disse no seu coração: Vêm chegando os dias de luto por meu pai; então matarei Jacó, meu irmão."},
{v:42,t:"Foram referidas a Rebeca as palavras de Esaú, seu filho mais velho; e ela mandou chamar Jacó, seu filho mais novo, e disse-lhe: Eis que Esaú, teu irmão, se consola com a ideia de te matar."},
{v:43,t:"Agora, pois, meu filho, ouve a minha voz: levanta-te e foge para Labão, meu irmão, em Harã;"},
{v:44,t:"ficarás com ele alguns dias, até que passe o furor de teu irmão,"},
{v:45,t:"até que se aplaque a ira dele contra ti e se esqueça do que lhe fizeste. Então mandarei buscar-te. Por que hei de perder os dois num só dia?",n:"Alguns dias hão de ser vinte anos, e Rebeca não tornará a ver o filho: o livro não conta a sua morte nem o reencontro. Foi ela quem armou tudo, e é ela quem paga com a ausência."},
{v:46,t:"E Rebeca disse a Isaac: Aborreço a vida por causa destas filhas de Het; se Jacó tomar mulher dentre as filhas de Het, como estas, dentre as filhas desta terra, para que me serve a vida?",n:"O verdadeiro motivo da partida era o ódio de Esaú; à frente de Isaac, Rebeca apresenta outro, que não é falso mas não é o principal. Nem com o marido ela deixa de manobrar."}
];

window.TEXTOS_SEED["genesis"][28] = [
{s:"Jacó enviado a Padã-Aram"},
{v:1,t:"Isaac chamou Jacó, abençoou-o e ordenou-lhe: Não tomes mulher dentre as filhas de Canaã."},
{v:2,t:"Levanta-te, vai a Padã-Aram, à casa de Batuel, pai de tua mãe, e toma dali mulher dentre as filhas de Labão, irmão de tua mãe."},
{v:3,t:"E que o Deus Todo-Poderoso te abençoe, te faça crescer e te multiplique, para que venhas a ser uma assembleia de povos;"},
{v:4,t:"e te dê a bênção de Abraão, a ti e à tua descendência contigo, para que possuas a terra das tuas peregrinações, que Deus deu a Abraão.",n:"Desta vez a bênção é dada com os olhos abertos e em plena luz. O que Jacó roubou no capítulo anterior recebe-o agora de mão beijada, e o livro parece querer refazer a cena direito."},
{v:5,t:"Isaac despediu Jacó, que partiu para Padã-Aram, para junto de Labão, filho de Batuel, o arameu, irmão de Rebeca, mãe de Jacó e de Esaú."},
{v:6,t:"Esaú viu que Isaac abençoara Jacó e o enviara a Padã-Aram, para tomar mulher de lá, e que, ao abençoá-lo, lhe ordenara: Não tomarás mulher dentre as filhas de Canaã;"},
{v:7,t:"e que Jacó, obedecendo a seu pai e a sua mãe, fora para Padã-Aram;"},
{v:8,t:"vendo, pois, Esaú que as filhas de Canaã desagradavam a Isaac, seu pai,"},
{v:9,t:"foi ter com Ismael e tomou por mulher, além das que já tinha, Maalat, filha de Ismael, filho de Abraão, irmã de Nabaiot.",n:"Esaú tenta agradar tarde demais, e da maneira errada: casa dentro da família, mas com a linha que fora posta de parte. É o retrato acabado de quem sempre chega depois."},
{s:"A escada de Betel"},
{v:10,t:"Jacó saiu de Bersabeia e foi para Harã."},
{v:11,t:"Chegou a certo lugar e ali passou a noite, porque o sol já se pusera; tomou uma das pedras do lugar, pô-la debaixo da cabeça e deitou-se ali.",n:"Foge com o que tem na mão: uma pedra por travesseiro. O homem que enganou o pai para ter tudo aparece aqui sem nada, e é nessa noite que Deus lhe fala pela primeira vez."},
{v:12,t:"E sonhou: eis uma escada posta na terra, cujo topo tocava o céu; e eis que os anjos de Deus subiam e desciam por ela."},
{v:13,t:"E eis que o Senhor estava em cima dela e dizia: Eu sou o Senhor, Deus de Abraão, teu pai, e Deus de Isaac. A terra em que estás deitado, eu a darei a ti e à tua descendência.",n:"A palavra hebraica designa antes uma rampa do que uma escada — como as que subiam pelos zigurates da Babilônia. A torre do capítulo 11 queria chegar ao céu e não chegou; aqui a ligação desce do alto, e chega sozinha a quem dorme. O Senhor Jesus retoma a imagem ao prometer a Natanael que verá os anjos de Deus subindo e descendo sobre o Filho do Homem."},
{v:14,t:"A tua descendência será como o pó da terra; hás de estender-te para o ocidente e para o oriente, para o norte e para o sul; e em ti e na tua descendência serão abençoadas todas as famílias da terra."},
{v:15,t:"E eis que eu estou contigo e te guardarei por onde quer que fores, e te farei voltar a esta terra; não te deixarei até ter cumprido o que te prometi.",n:"Deus não comenta a fraude nem a aprova: promete companhia. A promessa é feita a um fugitivo, no meio do caminho e no meio da noite."},
{v:16,t:"Jacó despertou do sono e disse: Verdadeiramente o Senhor está neste lugar, e eu não o sabia."},
{v:17,t:"E, tomado de temor, disse: Quão terrível é este lugar! Não é senão a casa de Deus e a porta do céu."},
{v:18,t:"Jacó levantou-se de manhã cedo, tomou a pedra que pusera debaixo da cabeça, erigiu-a como estela e derramou óleo sobre ela."},
{v:19,t:"E chamou àquele lugar Betel; antes, porém, a cidade se chamava Luza.",n:"Betel quer dizer casa de Deus. Havia de ser, séculos depois, um dos dois santuários do reino do Norte, e os profetas o atacariam por isso; a página guarda a memória de quando o lugar não era mais do que uma pedra ao relento."},
{v:20,t:"E Jacó fez um voto, dizendo: Se Deus for comigo e me guardar neste caminho que sigo, e me der pão para comer e roupa para vestir,"},
{v:21,t:"e eu voltar em paz à casa de meu pai, então o Senhor será o meu Deus;"},
{v:22,t:"e esta pedra, que erigi como estela, será casa de Deus; e de tudo quanto me deres, certamente te darei o dízimo.",n:"Até com Deus ele negocia, e põe condições. O voto de Jacó é sincero e é interesseiro ao mesmo tempo, e o livro não o corrige: deixa que os vinte anos seguintes o façam."}
];

window.TEXTOS_SEED["genesis"][29] = [
{s:"Jacó junto ao poço"},
{v:1,t:"Jacó pôs-se a caminho e foi à terra dos filhos do oriente."},
{v:2,t:"Olhou, e eis um poço no campo, e três rebanhos de ovelhas deitados junto dele, porque daquele poço se dava de beber aos rebanhos; e havia uma grande pedra sobre a boca do poço."},
{v:3,t:"Ali se ajuntavam todos os rebanhos; rolava-se a pedra da boca do poço, dava-se de beber às ovelhas e tornava-se a pôr a pedra sobre a boca do poço, no seu lugar."},
{v:4,t:"Jacó disse aos pastores: Irmãos, donde sois? Responderam: Somos de Harã."},
{v:5,t:"Perguntou-lhes: Conheceis Labão, filho de Nacor? Disseram: Conhecemos."},
{v:6,t:"E perguntou: Vai ele bem? Responderam: Vai bem; e eis Raquel, sua filha, que vem com as ovelhas."},
{v:7,t:"E ele disse: Ainda é pleno dia, e não é tempo de recolher o gado; dai de beber às ovelhas e ide apascentá-las."},
{v:8,t:"Responderam: Não podemos, enquanto não se ajuntarem todos os rebanhos e não se remover a pedra da boca do poço; então daremos de beber às ovelhas."},
{v:9,t:"Ainda falava com eles, quando chegou Raquel com as ovelhas de seu pai, pois era ela quem as apascentava."},
{v:10,t:"Assim que Jacó viu Raquel, filha de Labão, irmão de sua mãe, e as ovelhas de Labão, irmão de sua mãe, chegou-se, removeu a pedra da boca do poço e deu de beber ao rebanho de Labão, irmão de sua mãe.",n:"A pedra que exigia todos os pastores é removida por um homem só. E a frase repete três vezes irmão de sua mãe, como quem marca de que lado está o parentesco que vai custar-lhe vinte anos."},
{v:11,t:"Jacó beijou Raquel, levantou a voz e chorou;"},
{v:12,t:"e disse a Raquel que era parente de seu pai e filho de Rebeca. Ela correu e contou-o a seu pai."},
{v:13,t:"Quando Labão ouviu as notícias de Jacó, filho de sua irmã, correu-lhe ao encontro, abraçou-o, beijou-o e levou-o para casa. E Jacó contou a Labão tudo o que se passara."},
{v:14,t:"Labão disse-lhe: Tu és realmente osso meu e carne minha. E Jacó ficou com ele um mês inteiro."},
{s:"Lia e Raquel"},
{v:15,t:"Disse Labão a Jacó: Por seres meu parente, hás de servir-me de graça? Dize-me qual será o teu salário.",n:"A primeira frase de Labão é sobre dinheiro, e a palavra parente vem nela como argumento de negócio. O enganador encontrou o seu mestre."},
{v:16,t:"Labão tinha duas filhas: a mais velha chamava-se Lia, e a mais nova, Raquel."},
{v:17,t:"Lia tinha os olhos sem brilho, mas Raquel era formosa de porte e de rosto."},
{v:18,t:"Jacó amava Raquel, e disse: Sete anos te servirei por Raquel, tua filha mais nova."},
{v:19,t:"Respondeu Labão: Melhor é dá-la a ti do que a outro homem; fica comigo."},
{v:20,t:"Jacó serviu sete anos por Raquel; e pareceram-lhe poucos dias, pelo amor que lhe tinha.",n:"Uma das frases mais delicadas da Escritura, e está no meio de um capítulo de trapaça e de contratos. O narrador do Gênesis sabe onde pôr as suas meias linhas."},
{v:21,t:"Depois Jacó disse a Labão: Dá-me a minha mulher, porque o tempo está cumprido, para que me chegue a ela."},
{v:22,t:"Labão reuniu todos os homens do lugar e fez um banquete."},
{v:23,t:"À tarde tomou Lia, sua filha, e levou-a a Jacó; e ele se chegou a ela."},
{v:24,t:"E Labão deu a Zelfa, sua serva, a Lia, sua filha, por serva. Pela manhã Jacó olhou, e eis que era Lia!",n:"O homem que se fez passar pelo irmão mais velho, coberto por peles, recebe a irmã mais velha, coberta por um véu. O livro não precisa de comentar: basta-lhe a simetria."},
{v:25,t:"E disse a Labão: Que é isto que me fizeste? Não te servi eu por Raquel? Por que me enganaste?"},
{v:26,t:"Respondeu Labão: Não é costume na nossa terra dar a mais nova antes da mais velha.",n:"A resposta é uma ironia sem dó: Labão ensina ao suplantador que a ordem dos irmãos se respeita. É a lei que Jacó quebrara duas vezes com Esaú."},
{v:27,t:"Completa a semana desta, e também a outra se te dará, pelo serviço de mais sete anos."},
{v:28,t:"Assim fez Jacó: completou a semana daquela, e Labão deu-lhe por mulher Raquel, sua filha,"},
{v:29,t:"a quem deu por serva Bala, sua escrava."},
{v:30,t:"Jacó chegou-se também a Raquel, e amou-a mais do que a Lia; e serviu a Labão mais sete anos."},
{s:"Os filhos de Lia"},
{v:31,t:"O Senhor, vendo que Lia era desprezada, abriu-lhe a madre; Raquel, porém, era estéril.",n:"A que o marido não quer é a que Deus olha. Dos filhos desta mulher preterida hão de vir o sacerdócio, por Levi, e a realeza com o Messias, por Judá."},
{v:32,t:"Lia concebeu e deu à luz um filho, e chamou-lhe Rúben, dizendo: O Senhor viu a minha aflição; agora meu marido me amará."},
{v:33,t:"Concebeu outra vez e deu à luz um filho, e disse: O Senhor ouviu que eu era desprezada, e deu-me também este. E chamou-lhe Simeão."},
{v:34,t:"Concebeu pela terceira vez e deu à luz um filho, e disse: Agora, desta vez, meu marido se unirá a mim, porque lhe dei três filhos. Por isso lhe chamou Levi."},
{v:35,t:"Concebeu ainda e deu à luz um filho, e disse: Desta vez louvarei o Senhor. Por isso lhe chamou Judá. E cessou de dar à luz.",n:"Os três primeiros nomes são queixas dirigidas ao marido; o quarto já não fala dele. Judá soa como louvar, e é o único nome desta série que não pede nada."}
];

window.TEXTOS_SEED["genesis"][30] = [
{s:"As servas e os filhos"},
{v:1,t:"Vendo Raquel que não dava filhos a Jacó, teve inveja de sua irmã e disse ao marido: Dá-me filhos, senão morro."},
{v:2,t:"Jacó irou-se contra Raquel e disse: Estou eu no lugar de Deus, que te negou o fruto do ventre?"},
{v:3,t:"Ela disse: Eis a minha serva Bala; chega-te a ela, para que dê à luz sobre os meus joelhos, e assim também eu terei filhos por meio dela.",n:"Dar à luz sobre os joelhos de outra é o gesto jurídico da adoção: a criança passa a ser da que a recebe. É a mesma solução de Sara com Agar, e produz o mesmo azedume."},
{v:4,t:"Deu-lhe, pois, por mulher a sua serva Bala; e Jacó chegou-se a ela."},
{v:5,t:"Bala concebeu e deu um filho a Jacó."},
{v:6,t:"E Raquel disse: Deus me fez justiça; ouviu também a minha voz e deu-me um filho. Por isso lhe chamou Dã."},
{v:7,t:"Bala, serva de Raquel, concebeu outra vez e deu a Jacó um segundo filho."},
{v:8,t:"E Raquel disse: Lutas de Deus lutei com minha irmã, e venci. E chamou-lhe Neftali.",n:"A palavra que dá nome a Neftali é a da luta, e prepara o nome que Jacó há de receber no vau do Jaboc. Nesta casa todos lutam com todos, e a certa altura com Deus."},
{v:9,t:"Vendo Lia que cessara de dar à luz, tomou Zelfa, sua serva, e deu-a por mulher a Jacó."},
{v:10,t:"E Zelfa, serva de Lia, deu um filho a Jacó."},
{v:11,t:"E Lia disse: Que boa sorte! E chamou-lhe Gad."},
{v:12,t:"Zelfa, serva de Lia, deu a Jacó um segundo filho."},
{v:13,t:"E Lia disse: Feliz de mim! Porque as mulheres me chamarão feliz. E chamou-lhe Aser."},
{s:"As mandrágoras"},
{v:14,t:"Rúben saiu no tempo da ceifa do trigo e achou mandrágoras no campo, e levou-as a Lia, sua mãe. Raquel disse a Lia: Dá-me, peço-te, das mandrágoras de teu filho.",n:"A mandrágora passava por planta que fazia conceber, e o seu nome hebraico soa como a palavra amor. As duas irmãs disputam-na; e o filho virá, no verso 22, quando Deus se lembrar de Raquel, e não pela planta."},
{v:15,t:"Ela respondeu: Parece-te pouco teres-me tomado o marido, e queres tomar também as mandrágoras de meu filho? Disse Raquel: Pois que ele durma contigo esta noite, em troca das mandrágoras de teu filho."},
{v:16,t:"À tarde, quando Jacó voltava do campo, Lia saiu-lhe ao encontro e disse: Hás de vir a mim, porque te aluguei pelas mandrágoras de meu filho. E ele dormiu com ela naquela noite."},
{v:17,t:"Deus ouviu Lia, e ela concebeu e deu a Jacó um quinto filho."},
{v:18,t:"E disse: Deus deu-me a minha recompensa, porque dei a minha serva a meu marido. E chamou-lhe Issacar."},
{v:19,t:"Lia concebeu outra vez e deu a Jacó um sexto filho."},
{v:20,t:"E disse: Deus deu-me um bom dote; desta vez meu marido me honrará, porque lhe dei seis filhos. E chamou-lhe Zabulon."},
{v:21,t:"Depois deu à luz uma filha, e chamou-lhe Dina.",n:"Um verso só, sem etimologia e sem comentário, como se faz com as filhas nestas listas. O capítulo 34 há de contar o que lhe aconteceu."},
{v:22,t:"Deus lembrou-se de Raquel, ouviu-a e abriu-lhe a madre."},
{v:23,t:"Ela concebeu e deu à luz um filho, e disse: Deus tirou o meu opróbrio."},
{v:24,t:"E chamou-lhe José, dizendo: Que o Senhor me acrescente outro filho!",n:"José é ouvido de dois modos: tirou e acrescente. A mãe que acaba de receber um filho já pede o seguinte — e o segundo, Benjamim, há de custar-lhe a vida."},
{s:"Os rebanhos de Jacó"},
{v:25,t:"Depois que Raquel deu à luz José, Jacó disse a Labão: Deixa-me ir para o meu lugar e para a minha terra."},
{v:26,t:"Dá-me as minhas mulheres e os meus filhos, pelos quais te servi, e irei; pois tu sabes o serviço que te prestei."},
{v:27,t:"Labão disse-lhe: Se achei graça aos teus olhos, fica; por presságios aprendi que o Senhor me abençoou por tua causa."},
{v:28,t:"E acrescentou: Fixa tu o teu salário, e eu to darei."},
{v:29,t:"Respondeu Jacó: Tu sabes como te servi, e o que veio a ser o teu gado comigo."},
{v:30,t:"Pouco tinhas antes de eu chegar, e agora cresceu muitíssimo; o Senhor te abençoou desde que pus o pé aqui. Quando, porém, cuidarei eu também da minha casa?"},
{v:31,t:"Labão perguntou: Que te darei? Respondeu Jacó: Nada me darás; se fizeres o que te proponho, tornarei a apascentar e guardar o teu rebanho."},
{v:32,t:"Passarei hoje por todo o teu rebanho e porei de parte toda ovelha malhada e manchada, e toda ovelha escura entre os cordeiros, e as manchadas e malhadas entre as cabras: esse será o meu salário.",n:"Jacó escolhe para si o que é raro no gado da região: as ovelhas do Oriente são brancas, e as cabras, escuras. Pede, portanto, quase nada — e é aí que começa a sua vingança."},
{v:33,t:"E amanhã a minha honestidade responderá por mim: quando vieres verificar o meu salário, tudo o que não for malhado e manchado entre as cabras, e escuro entre os cordeiros, será tido por furtado por mim."},
{v:34,t:"Disse Labão: Está bem, seja como dizes."},
{v:35,t:"E naquele mesmo dia separou os bodes listrados e manchados, todas as cabras malhadas e manchadas, tudo o que tinha algo de branco, e todos os escuros entre os cordeiros, e entregou-os nas mãos de seus filhos.",n:"Mal fecha o trato, Labão tira do rebanho justamente os animais que Jacó havia de vir a ganhar, e põe três dias de caminho entre eles. O sogro rouba primeiro; o que Jacó fizer a seguir é resposta."},
{v:36,t:"E pôs a distância de três dias de caminho entre si e Jacó; e Jacó apascentava o resto do rebanho de Labão."},
{v:37,t:"Jacó tomou varas verdes de álamo, de amendoeira e de plátano, e descascou-as em partes, deixando aparecer o branco das varas."},
{v:38,t:"Pôs as varas que descascara nos bebedouros, onde se despejava a água, diante do rebanho, para que, vindo beber, concebesse olhando para elas."},
{v:39,t:"E o rebanho concebia diante das varas, e davam crias listradas, malhadas e manchadas.",n:"Da biologia, nada disto se sustenta; e o próprio Jacó, no capítulo seguinte, atribuirá o resultado a Deus, e não às varas. O narrador conta a artimanha com gosto, e depois deixa que ela seja desmentida."},
{v:40,t:"Jacó separou os cordeiros e voltou as faces do rebanho de Labão para o que era listrado e para tudo o que era escuro; e pôs à parte os seus próprios rebanhos, e não os juntou com o gado de Labão."},
{v:41,t:"E sempre que concebiam as ovelhas mais robustas, Jacó punha as varas nos bebedouros, diante dos olhos do rebanho, para que concebessem olhando para as varas."},
{v:42,t:"Mas, quando eram fracas, não as punha; assim as fracas ficavam para Labão, e as robustas para Jacó."},
{v:43,t:"E o homem enriqueceu extraordinariamente; teve muitos rebanhos, servas e servos, camelos e jumentos."}
];

window.TEXTOS_SEED["genesis"][31] = [
{s:"A fuga de Jacó"},
{v:1,t:"Jacó ouviu as palavras dos filhos de Labão, que diziam: Jacó tomou tudo o que era de nosso pai, e desta fazenda de nosso pai fez toda esta riqueza."},
{v:2,t:"E notou no rosto de Labão que ele já não era para com ele como antes."},
{v:3,t:"Então o Senhor disse a Jacó: Volta à terra de teus pais e à tua parentela, e eu serei contigo."},
{v:4,t:"Jacó mandou chamar Raquel e Lia ao campo, onde apascentava os rebanhos,"},
{v:5,t:"e disse-lhes: Vejo no rosto de vosso pai que ele já não é para comigo como antes; mas o Deus de meu pai esteve comigo."},
{v:6,t:"Vós mesmas sabeis que servi a vosso pai com todas as minhas forças."},
{v:7,t:"E vosso pai me enganou e mudou dez vezes o meu salário; contudo Deus não lhe permitiu fazer-me mal."},
{v:8,t:"Se dizia: As malhadas serão o teu salário, então todas as ovelhas davam crias malhadas; e se dizia: As listradas serão o teu salário, todos os rebanhos davam crias listradas."},
{v:9,t:"Assim Deus tirou o gado de vosso pai e deu-o a mim.",n:"No capítulo anterior a prosperidade vinha das varas descascadas; aqui Jacó a atribui inteira a Deus, e o sonho do verso 10 confirma-o. O livro deixa a artimanha e a providência uma em cima da outra, sem escolher."},
{v:10,t:"No tempo em que o rebanho concebia, levantei os olhos e vi em sonho que os machos que cobriam as fêmeas eram listrados, malhados e salpicados."},
{v:11,t:"E o anjo de Deus disse-me em sonho: Jacó! Eu respondi: Eis-me aqui."},
{v:12,t:"E ele disse: Levanta os olhos e vê: todos os machos que cobrem as fêmeas são listrados, malhados e salpicados, porque vi tudo o que Labão te fez."},
{v:13,t:"Eu sou o Deus de Betel, onde ungiste a pedra e me fizeste um voto. Levanta-te, pois, sai desta terra e volta à terra do teu nascimento."},
{v:14,t:"Responderam Raquel e Lia: Temos ainda parte ou herança na casa de nosso pai?"},
{v:15,t:"Não nos tratou ele como estranhas, vendendo-nos e comendo o nosso preço?",n:"Pela lei do lugar, o dote pago pelo noivo ficava em parte para a mulher; as duas acusam o pai de o ter comido todo. É a única vez que Lia e Raquel falam a uma só voz, e é contra Labão."},
{v:16,t:"Toda a riqueza que Deus tirou de nosso pai é nossa e de nossos filhos; faze, pois, tudo o que Deus te disse."},
{v:17,t:"Jacó levantou-se, pôs os filhos e as mulheres sobre os camelos,"},
{v:18,t:"e levou todo o seu gado e todos os bens que havia adquirido em Padã-Aram, para ir a Isaac, seu pai, na terra de Canaã."},
{v:19,t:"Labão tinha ido tosquiar as ovelhas; e Raquel furtou os ídolos domésticos de seu pai.",n:"Os terafim eram figuras da casa, ligadas à sorte da família e, ao que parece, ao título de herança. Raquel rouba-os sem que o marido saiba, e a cena seguinte é a mais divertida do livro."},
{v:20,t:"E Jacó enganou Labão, o arameu, não lhe dando notícia de que fugia."},
{v:21,t:"Fugiu com tudo o que tinha; e, passado o rio, dirigiu-se à montanha de Galaad."},
{s:"Labão persegue Jacó"},
{v:22,t:"Ao terceiro dia foi dito a Labão que Jacó havia fugido."},
{v:23,t:"Ele tomou consigo os seus irmãos, perseguiu-o por sete dias e alcançou-o na montanha de Galaad."},
{v:24,t:"Mas Deus veio a Labão, o arameu, em sonho, de noite, e disse-lhe: Guarda-te de falar a Jacó nem bem nem mal."},
{v:25,t:"Jacó já havia armado a sua tenda na montanha quando Labão, alcançando-o com os seus irmãos, armou também a sua na mesma montanha de Galaad."},
{v:26,t:"E Labão disse a Jacó: Que fizeste? Enganaste-me e levaste as minhas filhas como cativas de guerra."},
{v:27,t:"Por que fugiste às escondidas e me enganaste, sem me avisares? Eu te despediria com festa e cânticos, com tamboril e cítara."},
{v:28,t:"Não me deixaste beijar os meus filhos e as minhas filhas; obraste loucamente. Agora,"},
{v:29,t:"a minha mão teria poder para vos fazer mal, mas o Deus de vosso pai falou-me esta noite, dizendo: Guarda-te de falar a Jacó nem bem nem mal."},
{v:30,t:"Está bem que partisses, pois tinhas saudade da casa de teu pai; mas por que me furtaste os meus deuses?",n:"Depois de tanta retórica sentida, sai a verdadeira queixa: os ídolos. E Labão, que acabou de invocar o Deus dos pais, chama meus deuses às figuras de madeira."},
{v:31,t:"Respondeu Jacó: Porque tive medo; pensei que me tirasses as tuas filhas à força."},
{v:32,t:"Aquele com quem achares os teus deuses, morra! Examina diante dos nossos irmãos, e o que achares de teu, leva-o. Jacó não sabia que Raquel os tinha furtado.",n:"A sentença de morte é pronunciada, sem que Jacó o saiba, sobre a mulher que ama. Nesta família ninguém sabe o que o outro esconde."},
{v:33,t:"Labão entrou na tenda de Jacó, na de Lia e na das duas servas, e não achou nada. Saindo da tenda de Lia, entrou na de Raquel."},
{v:34,t:"Ela, porém, tinha escondido os ídolos na sela do camelo e estava sentada em cima; e Labão revistou toda a tenda e não achou nada."},
{v:35,t:"Ela disse-lhe: Não se irrite o meu senhor por eu não me poder levantar diante de ti, pois estou com o que costuma acontecer às mulheres. E ele procurou e não achou os ídolos.",n:"Os deuses do pai acabam debaixo de uma mulher que alega impureza, e ele não se atreve a olhar. É a mais dura zombaria que o Gênesis faz dos ídolos, e é feita sem uma palavra de doutrina."},
{s:"Vinte anos ao teu serviço"},
{v:36,t:"Jacó irou-se e reclamou de Labão, dizendo: Qual é a minha culpa, qual é o meu pecado, para me perseguires com tanto ardor,"},
{v:37,t:"e revistares todos os meus objetos? Que achaste de tudo o que é da tua casa? Põe-no aqui diante dos meus irmãos e dos teus, e que eles julguem entre mim e ti."},
{v:38,t:"Vinte anos estive contigo: as tuas ovelhas e as tuas cabras não abortaram, e não comi os carneiros do teu rebanho;"},
{v:39,t:"não te apresentei nenhum animal dilacerado pelas feras: eu pagava todo o prejuízo, e tudo o que se perdia de dia ou de noite tu o exigias de mim."},
{v:40,t:"De dia me consumia o calor, e de noite o frio; e o sono fugia dos meus olhos."},
{v:41,t:"Assim estive vinte anos em tua casa: catorze pelas tuas filhas e seis pelos teus rebanhos; e dez vezes mudaste o meu salário."},
{v:42,t:"Se o Deus de meu pai, o Deus de Abraão e o Temor de Isaac, não estivesse comigo, certamente me despedirias agora de mãos vazias. Deus viu a minha aflição e o trabalho das minhas mãos, e esta noite julgou.",n:"O Temor de Isaac é um dos nomes mais antigos e obscuros de Deus na Escritura, e só aparece neste capítulo. Entende-se como aquele a quem Isaac temia, ou, no vocabulário jurídico do tempo, como a garantia pela qual se jura."},
{s:"O monte do testemunho"},
{v:43,t:"Respondeu Labão: As filhas são minhas filhas, os filhos são meus filhos, os rebanhos são meus rebanhos, e tudo o que vês é meu; que poderei fazer hoje a estas minhas filhas e aos filhos que elas geraram?",n:"Até na despedida ele reclama tudo para si, quatro vezes, e acaba por não fazer nada. Labão é a figura do homem que só sabe possuir."},
{v:44,t:"Vem, pois, e façamos aliança, eu e tu, e sirva ela de testemunho entre mim e ti."},
{v:45,t:"Jacó tomou uma pedra e erigiu-a como estela;"},
{v:46,t:"e disse aos seus irmãos: Trazei pedras. Eles trouxeram pedras, fizeram um monte e comeram ali sobre ele."},
{v:47,t:"Labão chamou-lhe Jegar-Saaduta, e Jacó chamou-lhe Galed — cada um na sua própria língua.",n:"As duas expressões querem dizer a mesma coisa, monte do testemunho: uma em aramaico, a outra em hebraico. O detalhe marca que os dois homens já não falam a mesma língua, e explica o nome de Galaad."},
{v:48,t:"E Labão disse: Este monte é hoje testemunha entre mim e ti. Por isso lhe pôs o nome de Galed;"},
{v:49,t:"e também Masfa, isto é, Atalaia, porque disse: O Senhor vigie entre mim e ti, quando estivermos apartados um do outro."},
{v:50,t:"Se maltratares as minhas filhas, ou tomares outras mulheres além delas, não havendo ninguém conosco, vê: Deus é testemunha entre mim e ti."},
{v:51,t:"E disse Labão a Jacó: Eis este monte e esta pedra que erigi entre mim e ti."},
{v:52,t:"Este monte e esta pedra sejam testemunhas de que eu não passarei deste monte para o teu lado, nem tu passarás deste monte e desta pedra para o meu, com má intenção."},
{v:53,t:"O Deus de Abraão e o Deus de Nacor julguem entre nós. E Jacó jurou pelo Temor de seu pai Isaac;"},
{v:54,t:"e ofereceu sacrifícios na montanha, e chamou os seus irmãos para comerem pão. Comeram e passaram a noite na montanha.",n:"A aliança entre os dois não é de amizade, é de fronteira: cada um se obriga a não atravessar para o lado do outro. É a única solução que sobrou, e o livro apresenta-a como paz."}
];

window.TEXTOS_SEED["genesis"][32] = [
{s:"Os mensageiros a Esaú"},
{v:1,t:"Labão levantou-se de madrugada, beijou os filhos e as filhas, abençoou-os e voltou para o seu lugar."},
{v:2,t:"Jacó seguiu o seu caminho, e vieram ao seu encontro os anjos de Deus."},
{v:3,t:"Ao vê-los, Jacó disse: Este é o acampamento de Deus. E chamou àquele lugar Maanaim, isto é, Dois Acampamentos.",n:"Dois acampamentos: o dos anjos e o seu. O nome volta no verso 8, quando o medo o faz dividir o seu próprio povo em dois — a mesma palavra serve para a escolta invisível e para a estratégia de quem tem medo."},
{v:4,t:"Jacó enviou mensageiros adiante de si a Esaú, seu irmão, à terra de Seir, na região de Edom,"},
{v:5,t:"e ordenou-lhes: Assim falareis ao meu senhor Esaú: Isto diz o teu servo Jacó: Morei como estrangeiro em casa de Labão até ao dia de hoje."},
{v:6,t:"Tenho bois e jumentos, ovelhas, servos e servas; e mando dar notícia ao meu senhor, para achar graça aos teus olhos.",n:"Meu senhor, teu servo: o homem que comprou a primogenitura por um prato de lentilhas devolve a Esaú, na primeira frase, o lugar de mais velho."},
{v:7,t:"Os mensageiros voltaram a Jacó, dizendo: Fomos a Esaú, teu irmão, e ele vem ao teu encontro com quatrocentos homens."},
{v:8,t:"Jacó teve muito medo e, tomado de angústia, dividiu em dois grupos o povo que estava com ele, e os rebanhos, as ovelhas, os bois e os camelos,"},
{v:9,t:"dizendo: Se Esaú vier contra um dos grupos e o ferir, o outro que restar se salvará."},
{s:"A oração de Jacó"},
{v:10,t:"E Jacó disse: Deus de meu pai Abraão, Deus de meu pai Isaac, Senhor, que me disseste: Volta à tua terra e ao lugar do teu nascimento, e eu te farei bem;"},
{v:11,t:"sou indigno de todas as misericórdias e de toda a fidelidade que usaste com o teu servo. Com o meu cajado passei este Jordão, e agora volto com dois acampamentos.",n:"Primeira oração de Jacó em toda a sua vida, e não pede nada antes de confessar que não merece. O cajado e os dois acampamentos medem, num traço, os vinte anos."},
{v:12,t:"Livra-me da mão de meu irmão, da mão de Esaú, porque tenho muito medo dele, para que não venha e me fira, a mãe com os filhos."},
{v:13,t:"Tu disseste que me farias bem e multiplicarias a minha descendência como a areia do mar, que pela multidão não se pode contar."},
{s:"O presente para Esaú"},
{v:14,t:"Passou ali aquela noite e separou, do que tinha, um presente para Esaú, seu irmão:"},
{v:15,t:"duzentas cabras e vinte bodes, duzentas ovelhas e vinte carneiros,"},
{v:16,t:"trinta camelas de leite com as suas crias, quarenta vacas e dez touros, vinte jumentas e dez jumentinhos."},
{v:17,t:"Entregou-os às mãos dos seus servos, cada rebanho à parte, e disse-lhes: Passai adiante de mim, e haja espaço entre um rebanho e outro."},
{v:18,t:"E ordenou ao primeiro: Quando Esaú, meu irmão, te encontrar e te perguntar: De quem és? Para onde vais? De quem é isto que vai adiante de ti?"},
{v:19,t:"responderás: É do teu servo Jacó; é um presente que manda ao meu senhor Esaú; e ele mesmo vem atrás de nós."},
{v:20,t:"Deu a mesma ordem ao segundo, ao terceiro e a todos os que iam atrás dos rebanhos, dizendo: Falareis do mesmo modo a Esaú, quando o encontrardes,"},
{v:21,t:"e acrescentareis: O teu servo Jacó vem também atrás de nós. Porque dizia: Eu o apaziguarei com o presente que vai adiante, e depois verei o seu rosto; talvez ele me receba bem.",n:"A palavra que se traduz por apaziguar é a mesma que na Lei designa a expiação, e verei o seu rosto é a expressão de quem se apresenta ao rei. Todo o vocabulário do encontro com Esaú prepara o encontro desta noite."},
{v:22,t:"Os presentes seguiram adiante dele, e ele passou aquela noite no acampamento."},
{s:"A luta no Jaboc"},
{v:23,t:"Levantando-se de noite, tomou as suas duas mulheres, as duas servas e os onze filhos, e passou o vau do Jaboc."},
{v:24,t:"Depois de os fazer passar, com tudo o que lhe pertencia, pela torrente,"},
{v:25,t:"ficou sozinho. E eis que um homem lutou com ele até ao romper do dia.",n:"Um homem: o texto não diz mais, e é essa reserva que faz a cena. Jacó lutou toda a vida com o irmão, com o pai, com o sogro; a última luta é com alguém que o não quer dizer quem é."},
{v:26,t:"Vendo que não podia vencê-lo, tocou-lhe a articulação da coxa, e a coxa de Jacó se desconjuntou enquanto lutava com ele."},
{v:27,t:"E disse: Deixa-me ir, porque já vem a aurora. Respondeu: Não te deixarei ir, se não me abençoares.",n:"O homem que roubou a bênção do pai exige agora uma bênção, e exige-a de frente. É o mesmo desejo, e é outro homem quem o tem."},
{v:28,t:"Ele perguntou: Qual é o teu nome? Respondeu: Jacó."},
{v:29,t:"E disse: Já não te chamarás Jacó, mas Israel, porque lutaste com Deus e com os homens, e prevaleceste.",n:"Israel é ouvido como Deus luta ou lutou com Deus. O nome que era acusação, o suplantador, é trocado pelo nome de quem lutou de frente — e a troca vem com um osso deslocado."},
{v:30,t:"Jacó perguntou-lhe: Dize-me, por favor, qual é o teu nome. Respondeu: Por que perguntas pelo meu nome? E abençoou-o ali."},
{v:31,t:"E Jacó chamou àquele lugar Fanuel, dizendo: Vi Deus face a face, e a minha vida foi poupada."},
{v:32,t:"O sol nascia quando ele passou por Fanuel; e ia claudicando da coxa.",n:"Sai da noite com um nome novo e a andar mal. A bênção que recebeu não lhe tirou o defeito: deu-lho."},
{v:33,t:"Por isso os filhos de Israel não comem, até ao dia de hoje, o nervo que está na articulação da coxa, porque foi tocado o nervo da coxa de Jacó.",n:"A prescrição, que não vem em nenhuma das leis do Pentateuco, é observada ainda hoje: o açougueiro judeu retira esse nervo, ou não usa o quarto traseiro. Um costume alimentar nasce aqui de uma noite de luta."}
];

window.TEXTOS_SEED["genesis"][33] = [
{s:"O encontro com Esaú"},
{v:1,t:"Jacó levantou os olhos e viu que Esaú vinha, e com ele quatrocentos homens; e repartiu os filhos entre Lia, Raquel e as duas servas."},
{v:2,t:"Pôs à frente as duas servas e os seus filhos, em segundo lugar Lia e os seus filhos, e por último Raquel e José."},
{v:3,t:"E ele mesmo, passando adiante, prostrou-se em terra sete vezes, até se aproximar de seu irmão.",n:"Sete prostrações eram, nas cartas diplomáticas da época, o protocolo diante de um soberano. Jacó chega como vassalo, com a fila dos filhos ordenada do menos ao mais amado."},
{v:4,t:"Esaú correu ao seu encontro, abraçou-o, lançou-se-lhe ao pescoço, beijou-o, e ambos choraram.",n:"Quatro verbos, um atrás do outro, e nenhuma palavra. Todo o capítulo anterior de medo e de cálculo desfaz-se num abraço que Jacó não previu, e que o texto não explica."},
{v:5,t:"E, levantando os olhos, Esaú viu as mulheres e os filhos, e perguntou: Quem são estes que estão contigo? Respondeu: São os filhos que Deus concedeu ao teu servo."},
{v:6,t:"Aproximaram-se as servas com os seus filhos, e inclinaram-se."},
{v:7,t:"Aproximou-se também Lia com os seus filhos, e inclinaram-se; e por último inclinaram-se José e Raquel."},
{v:8,t:"E Esaú perguntou: Que significam todos esses rebanhos que encontrei? Respondeu: É para achar graça aos olhos do meu senhor."},
{v:9,t:"Disse Esaú: Tenho muito, meu irmão; guarda para ti o que é teu.",n:"O que vendeu a primogenitura por um prato de comida é agora o que diz: tenho muito. E chama-lhe meu irmão, palavra que Jacó não usa uma única vez em todo o diálogo."},
{v:10,t:"Respondeu Jacó: Não, peço-te; se achei graça aos teus olhos, aceita o meu presente das minhas mãos; porque vi o teu rosto como se visse o rosto de Deus, e me recebeste bem.",n:"No capítulo anterior ele viu Deus face a face e ficou vivo; agora diz o mesmo do rosto do irmão. O reencontro é lido como a outra metade da luta no Jaboc."},
{v:11,t:"Recebe, peço-te, a bênção que te foi trazida, porque Deus me favoreceu e tenho de tudo. E insistiu tanto que Esaú aceitou.",n:"Chama bênção ao presente, e emprega a mesma palavra que roubara no capítulo 27. Depois de vinte anos, devolve-a pelas próprias mãos."},
{v:12,t:"E Esaú disse: Vamos juntos; eu te acompanharei no caminho."},
{v:13,t:"Respondeu Jacó: O meu senhor sabe que as crianças são tenras, e que tenho comigo ovelhas e vacas de cria; se as fizer caminhar demais um só dia, morrerá todo o rebanho."},
{v:14,t:"Passe o meu senhor adiante do seu servo, e eu seguirei devagar, no passo dos rebanhos que vão à minha frente e no passo das crianças, até chegar a meu senhor, em Seir."},
{v:15,t:"Disse Esaú: Deixarei então contigo alguns dos homens que me acompanham. Respondeu: Não é preciso; basta-me achar graça aos olhos do meu senhor.",n:"Jacó promete ir a Seir e vai para Siquém, em direção contrária; e recusa a escolta. Reconciliado, continua a não confiar — o livro não lhe apara as arestas até ao fim."},
{v:16,t:"Naquele mesmo dia Esaú voltou pelo seu caminho, para Seir."},
{s:"Jacó em Siquém"},
{v:17,t:"E Jacó foi a Socot, onde edificou uma casa e armou tendas para os seus rebanhos; por isso chamou àquele lugar Socot, isto é, Tendas."},
{v:18,t:"Jacó chegou são e salvo à cidade de Siquém, na terra de Canaã, ao voltar de Padã-Aram; e acampou nas vizinhanças da cidade."},
{v:19,t:"E comprou aos filhos de Hemor, pai de Siquém, por cem moedas de prata, a parte do campo onde armara a sua tenda.",n:"Segundo pedaço de Canaã comprado por um patriarca, depois da caverna de Macpela. Ali havia de ser sepultado José, e ali o Evangelho de São João põe o poço da samaritana."},
{v:20,t:"E ali erigiu um altar, ao qual chamou: Deus é o Deus de Israel.",n:"O nome novo, recebido de noite no vau do rio, aparece aqui pela primeira vez gravado num altar, em terra própria. O ciclo que começou com uma pedra por travesseiro fecha-se com uma pedra por altar."}
];
